import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import { Game, loadRecords } from './game/engine';
import type { DiffId, HudData, MsgKind, Summary } from './game/engine';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import { GameOverScreen, Menu, PauseScreen } from './components/Screens';

type Screen = 'menu' | 'play' | 'paused' | 'over';
const PREFS_KEY = 'sky-ace-prefs';

function loadPrefs(): { diff: DiffId; invert: boolean; muted: boolean } {
  try {
    const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}');
    return { diff: p.diff || 'normal', invert: !!p.invert, muted: !!p.muted };
  } catch { return { diff: 'normal', invert: false, muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const overlayRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const timers = useRef<number[]>([]);
  const msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [invert, setInvert] = useState(prefs.invert);
  const [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));

  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.slice(-6), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), kind === 'kill' ? 2600 : 2000));
  }, []);

  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); if (g.mode === 'paused') setScreen('paused'); }
    else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
  }, []);

  useEffect(() => {
    if (!wrapRef.current || !overlayRef.current) return;
    const g = new Game(wrapRef.current, overlayRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 140, spread: 80, origin: { y: 0.35 }, colors: ['#ff7a1a', '#ffd166', '#ff4d6d', '#ffffff'] });
      },
    });
    g.input.onPause = togglePause;
    g.input.onAnyKey = () => g.sfx.unlock();
    gameRef.current = g;
    return () => {
      timers.current.forEach(t => clearTimeout(t)); timers.current = [];
      g.dispose(); gameRef.current = null;
    };
  }, [pushMsg, togglePause]);

  useEffect(() => { if (gameRef.current) gameRef.current.input.invert = invert; }, [invert]);
  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, invert, muted })); } catch { /* sin almacenamiento */ }
  }, [diff, invert, muted]);

  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null);
    g.input.invert = invert; g.setMuted(muted);
    g.start(diff);
    setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setScreen('menu'); setRecords(loadRecords()); };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#f2a47a] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => gameRef.current?.sfx.unlock()} />
      <canvas ref={overlayRef} className="absolute inset-0 pointer-events-none" />
      {(screen === 'play' || screen === 'paused') && (
        <Hud hud={hud} msgs={msgs} muted={muted} touch={touch} input={gameRef.current?.input ?? null}
          onMute={() => setMuted(m => !m)} onPause={togglePause} />
      )}
      {screen === 'menu' && (
        <Menu diff={diff} setDiff={setDiff} invert={invert} setInvert={setInvert} records={records}
          muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useRef } from 'react';
import type { PointerEvent as RPointerEvent } from 'react';
import { Crosshair, Flame, Pause, Rocket, Shield, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { HudData, MsgKind } from '../game/engine';
import type { Input } from '../game/input';

export interface Msg { id: number; text: string; kind: MsgKind }

interface Props {
  hud: HudData | null; msgs: Msg[]; muted: boolean; touch: boolean; input: Input | null;
  onMute: () => void; onPause: () => void;
}

function Bar({ value, color, label }: { value: number; color: string; label: string }) {
  return (
    <div className="w-full">
      <div className="flex justify-between text-[10px] tracking-[0.25em] text-white/70 mb-1"><span>{label}</span><span>{Math.round(value * 100)}%</span></div>
      <div className="h-2.5 w-full rounded-sm bg-black/50 ring-1 ring-white/15 overflow-hidden skew-x-[-18deg]">
        <div className="h-full transition-[width] duration-150" style={{ width: `${Math.max(0, Math.min(1, value)) * 100}%`, background: color, boxShadow: `0 0 12px ${color}` }} />
      </div>
    </div>
  );
}

export default function Hud({ hud, msgs, muted, touch, input, onMute, onPause }: Props) {
  if (!hud) return null;
  const hpColor = hud.hp > 50 ? '#5dff9a' : hud.hp > 25 ? '#ffd166' : '#ff4d3d';
  const banners = msgs.filter(m => m.kind !== 'kill').slice(-2);
  const feed = msgs.filter(m => m.kind === 'kill').slice(-4);
  return (
    <div className="absolute inset-0 pointer-events-none text-white font-mono select-none">
      {/* Marcador */}
      <div className="absolute left-4 top-4">
        <div className="text-[10px] tracking-[0.35em] text-orange-300/90">PUNTOS</div>
        <div className="text-3xl sm:text-4xl font-black italic tabular-nums drop-shadow-[0_2px_8px_rgba(0,0,0,0.6)]">{hud.score.toLocaleString('es-ES')}</div>
        <div className="mt-1 flex items-center gap-3 text-xs text-white/80">
          <span className="rounded bg-black/40 px-2 py-0.5 ring-1 ring-white/10">OLEADA <b className="text-orange-300">{hud.wave}</b></span>
          <span className="rounded bg-black/40 px-2 py-0.5 ring-1 ring-white/10">HOSTILES <b className="text-rose-400">{hud.enemies}</b></span>
          {hud.combo > 1 && <span className="rounded bg-orange-500/80 px-2 py-0.5 font-bold animate-pulse">x{hud.combo}</span>}
        </div>
        <div className="mt-3 space-y-1">
          {feed.map(m => <div key={m.id} className="text-xs text-amber-200/95 drop-shadow">✦ {m.text}</div>)}
        </div>
      </div>

      {/* Botones */}
      <div className="absolute right-4 top-4 flex gap-2 pointer-events-auto">
        <button aria-label="Silencio" onClick={onMute} className="h-9 w-9 grid place-items-center rounded-md bg-black/40 ring-1 ring-white/20 hover:bg-black/60">
          {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
        </button>
        <button aria-label="Pausa" onClick={onPause} className="h-9 w-9 grid place-items-center rounded-md bg-black/40 ring-1 ring-white/20 hover:bg-black/60">
          <Pause size={18} />
        </button>
      </div>

      {/* Banners centrales */}
      <div className="absolute top-[18%] left-0 right-0 flex flex-col items-center gap-2">
        {banners.map(m => (
          <div key={m.id} className={clsx('px-6 py-1.5 font-black italic tracking-[0.2em] drop-shadow-[0_2px_10px_rgba(0,0,0,0.7)]',
            m.kind === 'big' && 'text-4xl sm:text-5xl text-white',
            m.kind === 'warn' && 'text-xl sm:text-2xl text-rose-400 animate-pulse',
            m.kind === 'good' && 'text-xl sm:text-2xl text-emerald-300')}>{m.text}</div>
        ))}
        {hud.missileWarn && <div className="mt-1 rounded bg-rose-600/80 px-4 py-1 text-sm font-bold tracking-[0.3em] animate-pulse">⚠ MISIL ENTRANTE · ¡VIRA!</div>}
        {hud.lowAlt && <div className="rounded bg-amber-500/80 px-4 py-1 text-sm font-bold tracking-[0.3em] animate-pulse">¡ALTITUD! ¡SUBE!</div>}
        {hud.outOfBounds && <div className="rounded bg-sky-600/80 px-4 py-1 text-sm font-bold tracking-[0.3em]">REGRESA A LA ZONA DE COMBATE</div>}
      </div>

      {/* Panel inferior */}
      <div className={clsx('absolute left-1/2 -translate-x-1/2 bottom-4 w-[min(560px,92vw)] rounded-xl bg-slate-950/45 backdrop-blur-sm ring-1 ring-white/10 px-4 py-3', touch && 'bottom-auto top-[64px] scale-90')}>
        <div className="grid grid-cols-[1fr_auto_1fr] gap-4 items-center">
          <div className="space-y-2">
            <Bar value={hud.hp / 100} color={hpColor} label="BLINDAJE" />
            <Bar value={hud.boost} color="#7fd4ff" label="TURBO" />
          </div>
          <div className="text-center px-2">
            <div className="text-2xl font-black tabular-nums leading-none">{hud.speed}</div>
            <div className="text-[9px] tracking-[0.3em] text-white/60">KM/H</div>
            <div className="mt-1 text-sm font-bold tabular-nums text-sky-200">{hud.alt} m</div>
          </div>
          <div>
            <div className="text-[10px] tracking-[0.25em] text-white/70 mb-1 flex items-center gap-1"><Rocket size={11} /> MISILES</div>
            <div className="flex gap-1">
              {Array.from({ length: hud.maxMissiles }).map((_, i) => (
                <div key={i} className={clsx('h-4 w-2 rounded-t-full', i < hud.missiles ? 'bg-orange-400 shadow-[0_0_8px_#fb923c]' : 'bg-white/15')} />
              ))}
            </div>
            <div className={clsx('mt-1.5 text-[10px] tracking-[0.2em] flex items-center gap-1', hud.locked ? 'text-emerald-300' : 'text-white/50')}>
              <Crosshair size={11} /> {hud.locked ? `FIJADO · ${hud.lockName}` : hud.lockName ? `FIJANDO ${hud.lockName}…` : 'SIN BLANCO'}
            </div>
          </div>
        </div>
        {(hud.rapidT > 0 || hud.shieldT > 0) && (
          <div className="mt-2 flex gap-2 justify-center text-[11px] font-bold">
            {hud.rapidT > 0 && <span className="flex items-center gap-1 rounded bg-amber-500/80 px-2 py-0.5"><Flame size={12} /> FUEGO RÁPIDO {Math.ceil(hud.rapidT)}s</span>}
            {hud.shieldT > 0 && <span className="flex items-center gap-1 rounded bg-cyan-500/80 px-2 py-0.5"><Shield size={12} /> ESCUDO {Math.ceil(hud.shieldT)}s</span>}
          </div>
        )}
      </div>

      {touch && input && <TouchControls input={input} />}
    </div>
  );
}

function TouchControls({ input }: { input: Input }) {
  const base = useRef<HTMLDivElement>(null);
  const knob = useRef<HTMLDivElement>(null);
  const move = (e: RPointerEvent<HTMLDivElement>) => {
    const el = base.current; if (!el) return;
    const r = el.getBoundingClientRect();
    const R = r.width / 2;
    let dx = (e.clientX - r.left - R) / R, dy = (e.clientY - r.top - R) / R;
    const l = Math.hypot(dx, dy); if (l > 1) { dx /= l; dy /= l; }
    input.touch.active = true; input.touch.roll = dx; input.touch.pitch = -dy;
    if (knob.current) knob.current.style.transform = `translate(${dx * R * 0.6}px, ${dy * R * 0.6}px)`;
  };
  const end = () => {
    input.touch.active = false; input.touch.roll = 0; input.touch.pitch = 0;
    if (knob.current) knob.current.style.transform = 'translate(0,0)';
  };
  const hold = (key: 'fire' | 'boost', v: boolean) => () => { input.touch[key] = v; };
  return (
    <>
      <div ref={base} className="pointer-events-auto absolute left-6 bottom-6 h-36 w-36 rounded-full bg-white/10 ring-2 ring-white/25 touch-none grid place-items-center"
        onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); move(e); }} onPointerMove={e => { if (input.touch.active) move(e); }}
        onPointerUp={end} onPointerCancel={end}>
        <div ref={knob} className="h-14 w-14 rounded-full bg-white/40 ring-2 ring-white/60 pointer-events-none" />
      </div>
      <div className="pointer-events-auto absolute right-5 bottom-6 flex items-end gap-3 touch-none">
        <button aria-label="Turbo" className="h-14 w-14 rounded-full bg-sky-500/50 ring-2 ring-sky-200/60 grid place-items-center active:bg-sky-400/80"
          onPointerDown={hold('boost', true)} onPointerUp={hold('boost', false)} onPointerLeave={hold('boost', false)}><Zap /></button>
        <button aria-label="Misil" className="h-16 w-16 rounded-full bg-orange-500/50 ring-2 ring-orange-200/60 grid place-items-center active:bg-orange-400/80"
          onPointerDown={() => { input.state.missile = true; }}><Rocket /></button>
        <button aria-label="Disparar" className="h-20 w-20 rounded-full bg-rose-600/60 ring-2 ring-rose-200/60 grid place-items-center font-bold text-xs active:bg-rose-500/90"
          onPointerDown={hold('fire', true)} onPointerUp={hold('fire', false)} onPointerLeave={hold('fire', false)}><Crosshair /></button>
      </div>
    </>
  );
}

import { Crosshair, Home, Play, Plane, RotateCcw, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { DIFFS } from '../game/engine';
import type { DiffId, Summary } from '../game/engine';

const TITLE_FONT = { fontFamily: '"Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", system-ui, sans-serif' };

const KEYS: Array<[string, string]> = [
  ['↑ ↓ / W S', 'Cabeceo'], ['← → / A D', 'Alabeo y viraje'], ['Espacio', 'Ametralladora'],
  ['X / M', 'Misil (fija el blanco)'], ['Shift', 'Turbo'], ['P / Esc', 'Pausa'],
];

interface MenuProps {
  diff: DiffId; setDiff: (d: DiffId) => void; invert: boolean; setInvert: (v: boolean) => void;
  records: Record<DiffId, number>; muted: boolean; onMute: () => void; onPlay: () => void;
}

export function Menu({ diff, setDiff, invert, setInvert, records, muted, onMute, onPlay }: MenuProps) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-slate-950/85 via-slate-950/40 to-transparent text-white">
      <div className="min-h-full flex items-center p-4 sm:p-10">
        <div className="w-full max-w-[460px]">
          <div className="flex items-center gap-2 text-orange-300 text-xs tracking-[0.5em] font-mono"><Plane size={14} /> ESCUADRÓN ÁMBAR</div>
          <h1 style={TITLE_FONT} className="mt-2 text-6xl sm:text-7xl font-black italic leading-[0.85] tracking-tight bg-gradient-to-br from-amber-200 via-orange-400 to-rose-500 bg-clip-text text-transparent drop-shadow-[0_4px_24px_rgba(255,120,40,0.35)]">
            SKY ACE
          </h1>
          <div style={TITLE_FONT} className="text-xl italic font-bold tracking-[0.35em] text-white/90">AS DEL CIELO</div>
          <p className="mt-3 text-sm text-white/75 leading-relaxed">
            El archipiélago está bajo ataque. Despega al atardecer, fija blancos con tu radar y derriba oleada tras oleada de cazas,
            interceptores y bombarderos antes de que dominen el cielo.
          </p>

          <div className="mt-5 text-[10px] font-mono tracking-[0.35em] text-white/60">DIFICULTAD</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {(Object.keys(DIFFS) as DiffId[]).map(id => (
              <button key={id} onClick={() => setDiff(id)}
                className={clsx('rounded-lg px-2 py-2 text-left ring-1 transition', diff === id ? 'bg-orange-500/90 ring-orange-200 shadow-[0_0_20px_rgba(255,140,40,0.45)]' : 'bg-white/5 ring-white/15 hover:bg-white/10')}>
                <div style={TITLE_FONT} className="font-black italic tracking-wider">{DIFFS[id].label.toUpperCase()}</div>
                <div className="text-[10px] leading-tight text-white/75">{DIFFS[id].sub}</div>
              </button>
            ))}
          </div>

          <div className="mt-3 flex items-center justify-between gap-3">
            <label className="flex items-center gap-2 text-xs text-white/80 cursor-pointer">
              <input type="checkbox" checked={invert} onChange={e => setInvert(e.target.checked)} className="accent-orange-500 h-4 w-4" />
              Invertir eje vertical (estilo simulador)
            </label>
            <button aria-label="Silencio" onClick={onMute} className="h-8 w-8 grid place-items-center rounded-md bg-white/10 ring-1 ring-white/20">
              {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
          </div>

          <div className="mt-4 flex items-center gap-3 rounded-lg bg-black/30 ring-1 ring-white/10 px-3 py-2">
            <Trophy className="text-amber-300" size={20} />
            <div className="text-xs text-white/70">Récord ({DIFFS[diff].label})</div>
            <div className="ml-auto font-mono text-lg font-bold text-amber-200">{records[diff].toLocaleString('es-ES')}</div>
          </div>

          <button onClick={onPlay}
            className="mt-5 w-full flex items-center justify-center gap-3 rounded-xl bg-gradient-to-r from-orange-500 to-rose-500 py-4 text-2xl font-black italic tracking-[0.2em] shadow-[0_10px_40px_rgba(255,90,40,0.45)] hover:brightness-110 active:scale-[0.98] transition"
            style={TITLE_FONT}>
            <Play fill="currentColor" size={22} /> Jugar
          </button>

          <div className="mt-5 grid grid-cols-2 gap-x-4 gap-y-1 text-xs">
            {KEYS.map(([k, v]) => (
              <div key={k} className="flex gap-2"><span className="font-mono text-orange-200 whitespace-nowrap">{k}</span><span className="text-white/60">{v}</span></div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function Panel({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-slate-950/55 backdrop-blur-[3px] p-4 text-white">
      <div className="w-full max-w-sm rounded-2xl bg-slate-900/85 ring-1 ring-white/15 p-6 shadow-2xl">{children}</div>
    </div>
  );
}

const btn = 'w-full flex items-center justify-center gap-2 rounded-lg py-3 font-bold tracking-wider transition active:scale-[0.98]';

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <h2 style={TITLE_FONT} className="text-4xl font-black italic text-center tracking-widest">PAUSA</h2>
      <p className="text-center text-xs text-white/60 mt-1">Pulsa P o Esc para continuar</p>
      <div className="mt-5 space-y-2">
        <button onClick={onResume} className={clsx(btn, 'bg-orange-500 hover:bg-orange-400')}><Play size={18} /> Continuar</button>
        <button onClick={onRestart} className={clsx(btn, 'bg-white/10 hover:bg-white/20')}><RotateCcw size={18} /> Reiniciar</button>
        <button onClick={onMenu} className={clsx(btn, 'bg-white/10 hover:bg-white/20')}><Home size={18} /> Menú principal</button>
      </div>
    </Panel>
  );
}

export function GameOverScreen({ s, onRetry, onMenu }: { s: Summary; onRetry: () => void; onMenu: () => void }) {
  const stats: Array<[string, string]> = [
    ['Oleada alcanzada', String(s.wave)], ['Derribos', String(s.kills)], ['Precisión', `${s.accuracy}%`],
    ['Mejor combo', `x${s.bestCombo}`], ['Tiempo de vuelo', `${Math.floor(s.time / 60)}:${String(s.time % 60).padStart(2, '0')}`],
    ['Dificultad', DIFFS[s.diff].label],
  ];
  return (
    <Panel>
      <h2 style={TITLE_FONT} className="text-3xl font-black italic text-center tracking-widest text-rose-400">MISIÓN TERMINADA</h2>
      {s.newRecord && <div className="mt-2 text-center font-black italic text-amber-300 animate-pulse flex items-center justify-center gap-2"><Trophy size={18} /> ¡NUEVO RÉCORD!</div>}
      <div className="mt-3 text-center">
        <div className="text-[10px] tracking-[0.4em] text-white/60 font-mono">PUNTUACIÓN</div>
        <div className="text-5xl font-black font-mono">{s.score.toLocaleString('es-ES')}</div>
        <div className="text-xs text-white/50 mt-1">Récord: {s.record.toLocaleString('es-ES')}</div>
      </div>
      <div className="mt-4 grid grid-cols-2 gap-2 text-sm">
        {stats.map(([k, v]) => (
          <div key={k} className="rounded-lg bg-white/5 px-3 py-2"><div className="text-[10px] text-white/50">{k}</div><div className="font-bold">{v}</div></div>
        ))}
      </div>
      <div className="mt-5 space-y-2">
        <button onClick={onRetry} className={clsx(btn, 'bg-orange-500 hover:bg-orange-400')}><Crosshair size={18} /> Reintentar</button>
        <button onClick={onMenu} className={clsx(btn, 'bg-white/10 hover:bg-white/20')}><Home size={18} /> Menú principal</button>
      </div>
    </Panel>
  );
}

/** Audio procedural con Web Audio API: motor, disparos, misiles, explosiones y avisos. */
export class Sfx {
  ctx: AudioContext | null = null;
  master: GainNode | null = null;
  muted = false;
  private noiseBuf: AudioBuffer | null = null;
  private eng: { o1: OscillatorNode; o2: OscillatorNode; gain: GainNode; filter: BiquadFilterNode } | null = null;
  private lastGun = 0; private warnT = 0;

  /** Llamar en el primer gesto del usuario. */
  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    const AC: typeof AudioContext | undefined = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    const len = this.ctx.sampleRate * 1.5;
    this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  /** Zumbido del motor: dos osciladores + viento filtrados. */
  startEngine() {
    if (!this.ctx || !this.master || this.eng) return;
    const c = this.ctx;
    const gain = c.createGain(); gain.gain.value = 0;
    const filter = c.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = 500;
    const o1 = c.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 70;
    const o2 = c.createOscillator(); o2.type = 'square'; o2.frequency.value = 35.5;
    const g2 = c.createGain(); g2.gain.value = 0.4;
    o1.connect(filter); o2.connect(g2); g2.connect(filter);
    if (this.noiseBuf) {
      const n = c.createBufferSource(); n.buffer = this.noiseBuf; n.loop = true;
      const f = c.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 0.6;
      const ng = c.createGain(); ng.gain.value = 0.25;
      n.connect(f); f.connect(ng); ng.connect(filter); n.start();
      o1.addEventListener('ended', () => { try { n.stop(); } catch { /* ya parado */ } });
    }
    filter.connect(gain); gain.connect(this.master);
    o1.start(); o2.start();
    gain.gain.setTargetAtTime(0.12, c.currentTime, 0.4);
    this.eng = { o1, o2, gain, filter };
  }

  setEngine(throttle: number, boost: boolean) {
    if (!this.ctx || !this.eng) return;
    const t = this.ctx.currentTime, f = 60 + throttle * 50 + (boost ? 40 : 0);
    this.eng.o1.frequency.setTargetAtTime(f, t, 0.15);
    this.eng.o2.frequency.setTargetAtTime(f / 2 + 0.7, t, 0.15);
    this.eng.filter.frequency.setTargetAtTime(boost ? 1600 : 650, t, 0.2);
  }

  stopEngine() {
    if (!this.ctx || !this.eng) return;
    const e = this.eng; this.eng = null;
    e.gain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1);
    setTimeout(() => { try { e.o1.stop(); e.o2.stop(); e.gain.disconnect(); } catch { /* ya parado */ } }, 400);
  }

  private env(dur: number, peak: number) {
    const c = this.ctx!; const g = c.createGain();
    g.gain.setValueAtTime(peak, c.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + dur);
    g.connect(this.master!);
    return g;
  }
  private noise(dur: number, freq: number, peak: number, type: BiquadFilterType = 'lowpass') {
    if (!this.ctx || !this.master || !this.noiseBuf) return;
    const c = this.ctx; const s = c.createBufferSource(); s.buffer = this.noiseBuf;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.value = freq;
    s.connect(f); f.connect(this.env(dur, peak));
    s.start(c.currentTime, Math.random()); s.stop(c.currentTime + dur);
  }
  private tone(type: OscillatorType, f0: number, f1: number, dur: number, peak: number) {
    if (!this.ctx || !this.master) return;
    const c = this.ctx; const o = c.createOscillator(); o.type = type;
    o.frequency.setValueAtTime(f0, c.currentTime);
    o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), c.currentTime + dur);
    o.connect(this.env(dur, peak)); o.start(); o.stop(c.currentTime + dur);
  }

  gun() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime; if (now - this.lastGun < 0.055) return; this.lastGun = now;
    this.noise(0.07, 2600, 0.22, 'bandpass'); this.tone('square', 180, 60, 0.06, 0.08);
  }
  enemyGun(vol: number) { if (vol > 0.05) this.noise(0.06, 1500, 0.12 * vol, 'bandpass'); }
  missile() { this.noise(0.9, 700, 0.35); this.tone('sawtooth', 300, 900, 0.5, 0.06); }
  hit() { this.tone('square', 900, 300, 0.05, 0.08); }
  hurt() { this.noise(0.25, 400, 0.4); this.tone('triangle', 200, 60, 0.25, 0.25); }
  explosion(vol = 1) { this.noise(1.4, 500, 0.9 * vol); this.noise(0.4, 2400, 0.3 * vol); this.tone('sine', 120, 30, 0.8, 0.5 * vol); }
  pickup() { this.tone('triangle', 520, 1040, 0.15, 0.2); setTimeout(() => this.tone('triangle', 780, 1560, 0.18, 0.2), 90); }
  lockTick() { this.tone('square', 1200, 1200, 0.04, 0.05); }
  locked() { this.tone('square', 1760, 1760, 0.12, 0.07); }
  warning(t: number) { if (t - this.warnT < 0.35) return; this.warnT = t; this.tone('square', 980, 980, 0.12, 0.08); }
  fanfare() { [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => this.tone('triangle', f, f, 0.25, 0.18), i * 120)); }

  dispose() {
    this.stopEngine();
    const c = this.ctx; this.ctx = null; this.master = null;
    if (c) setTimeout(() => c.close().catch(() => {}), 450);
  }
}

import * as THREE from 'three';
import type { Effects } from './effects';
import { getGlowTexture } from './models';

/** Cualquier cosa que pueda recibir disparos o ser perseguida por un misil. */
export interface Target { pos: THREE.Vector3; vel: THREE.Vector3; alive: boolean; radius: number }

export type Owner = 'player' | 'enemy';
export type PickupKind = 'repair' | 'missiles' | 'rapid' | 'shield';
export const PICKUP_INFO: Record<PickupKind, { color: string; label: string }> = {
  repair: { color: '#4dff88', label: 'REPARACIÓN' },
  missiles: { color: '#4db8ff', label: '+MISILES' },
  rapid: { color: '#ffb02e', label: 'FUEGO RÁPIDO' },
  shield: { color: '#7ef9ff', label: 'ESCUDO' },
};

interface Bullet { pos: THREE.Vector3; vel: THREE.Vector3; life: number; owner: Owner; dmg: number }
export interface Missile {
  mesh: THREE.Group; pos: THREE.Vector3; dir: THREE.Vector3; speed: number; life: number;
  owner: Owner; target: Target | null; active: boolean; turn: number;
}
export interface Pickup { mesh: THREE.Group; kind: PickupKind; pos: THREE.Vector3; life: number }

export interface CombatHooks {
  player: Target;
  enemies: Target[];
  heightAt: (x: number, z: number) => number;
  onEnemyHit: (t: Target, dmg: number, p: THREE.Vector3, byMissile: boolean) => void;
  onPlayerHit: (dmg: number, p: THREE.Vector3) => void;
  onPickup: (k: PickupKind) => void;
}

const MAX_BULLETS = 260;
const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _c = new THREE.Vector3();
const dummy = new THREE.Object3D();

/** Distancia mínima entre el segmento [p, p+d] y el punto c. */
function segDist2(p: THREE.Vector3, d: THREE.Vector3, c: THREE.Vector3) {
  _a.subVectors(c, p);
  const l2 = d.lengthSq();
  const t = l2 > 0 ? Math.max(0, Math.min(1, _a.dot(d) / l2)) : 0;
  _b.copy(p).addScaledVector(d, t);
  return { d2: _b.distanceToSquared(c), point: _b };
}

export class Combat {
  bullets: Bullet[] = [];
  missiles: Missile[] = [];
  pickups: Pickup[] = [];
  shotsFired = 0; shotsHit = 0;
  private scene: THREE.Scene;
  private tracerP: THREE.InstancedMesh; private tracerE: THREE.InstancedMesh;
  private disposables: Array<{ dispose: () => void }> = [];
  private pickupGeo = new THREE.OctahedronGeometry(5, 0);
  private ringGeo = new THREE.TorusGeometry(9, 0.6, 6, 24);

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    const g = new THREE.BoxGeometry(1.3, 1.3, 46);
    const mk = (color: string) => {
      const m = new THREE.MeshBasicMaterial({ color, fog: false });
      const im = new THREE.InstancedMesh(g, m, MAX_BULLETS);
      im.frustumCulled = false; im.count = 0; scene.add(im);
      this.disposables.push(m);
      return im;
    };
    this.tracerP = mk('#ffd83a'); this.tracerE = mk('#ff3b2f');
    this.disposables.push(g, this.pickupGeo, this.ringGeo);
    // Pool de misiles
    const body = new THREE.CylinderGeometry(0.35, 0.35, 4.2, 6).rotateX(Math.PI / 2);
    const tip = new THREE.ConeGeometry(0.35, 1.2, 6).rotateX(-Math.PI / 2).translate(0, 0, -2.7);
    const finG = new THREE.BoxGeometry(1.6, 0.1, 0.6).translate(0, 0, 1.8);
    const mBody = new THREE.MeshStandardMaterial({ color: '#e8e8e8', metalness: 0.3, roughness: 0.5 });
    const mTip = new THREE.MeshStandardMaterial({ color: '#d02020', emissive: '#601010' });
    this.disposables.push(body, tip, finG, mBody, mTip);
    for (let i = 0; i < 28; i++) {
      const grp = new THREE.Group();
      const f2 = new THREE.Mesh(finG, mBody); f2.rotation.z = Math.PI / 2;
      grp.add(new THREE.Mesh(body, mBody), new THREE.Mesh(tip, mTip), new THREE.Mesh(finG, mBody), f2);
      const glowMat = new THREE.SpriteMaterial({ map: getGlowTexture(), color: '#ffb060', blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, fog: false });
      const glow = new THREE.Sprite(glowMat); glow.position.z = 2.8; glow.scale.set(6, 6, 1); grp.add(glow);
      this.disposables.push(glowMat);
      grp.visible = false; scene.add(grp);
      this.missiles.push({ mesh: grp, pos: new THREE.Vector3(), dir: new THREE.Vector3(), speed: 0, life: 0, owner: 'player', target: null, active: false, turn: 2 });
    }
  }

  fireBullet(pos: THREE.Vector3, vel: THREE.Vector3, owner: Owner, dmg: number) {
    let b: Bullet | undefined;
    if (this.bullets.length < MAX_BULLETS * 2) {
      b = { pos: pos.clone(), vel: vel.clone(), life: 1.2, owner, dmg }; this.bullets.push(b);
    }
    if (owner === 'player') this.shotsFired++;
    return b;
  }

  fireMissile(pos: THREE.Vector3, dir: THREE.Vector3, speed: number, owner: Owner, target: Target | null) {
    const m = this.missiles.find(x => !x.active); if (!m) return null;
    m.active = true; m.pos.copy(pos); m.dir.copy(dir).normalize(); m.speed = speed; m.owner = owner;
    m.target = target; m.life = owner === 'player' ? 6 : 7.5; m.turn = owner === 'player' ? 2.8 : 1.15;
    m.mesh.visible = true;
    return m;
  }

  spawnPickup(pos: THREE.Vector3, kind?: PickupKind) {
    const kinds: PickupKind[] = ['repair', 'missiles', 'rapid', 'shield'];
    const k = kind || kinds[Math.floor(Math.random() * kinds.length)];
    const col = PICKUP_INFO[k].color;
    const grp = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color: col, emissive: col, emissiveIntensity: 0.9, flatShading: true });
    const ringMat = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false });
    const glowMat = new THREE.SpriteMaterial({ map: getGlowTexture(), color: col, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false });
    const glow = new THREE.Sprite(glowMat); glow.scale.set(40, 40, 1);
    grp.add(new THREE.Mesh(this.pickupGeo, mat), new THREE.Mesh(this.ringGeo, ringMat), glow);
    grp.position.copy(pos); grp.position.y = Math.max(grp.position.y, 90);
    this.scene.add(grp);
    this.pickups.push({ mesh: grp, kind: k, pos: grp.position, life: 30 });
  }

  private removePickup(i: number) {
    const p = this.pickups[i];
    this.scene.remove(p.mesh);
    p.mesh.traverse(o => { const m = (o as THREE.Mesh).material as THREE.Material | undefined; if (m) m.dispose(); });
    this.pickups.splice(i, 1);
  }

  update(dt: number, t: number, h: CombatHooks, fx: Effects) {
    // --- Balas ---
    let np = 0, ne = 0;
    for (let i = this.bullets.length - 1; i >= 0; i--) {
      const b = this.bullets[i];
      b.life -= dt;
      _c.copy(b.vel).multiplyScalar(dt);
      let hit = false;
      if (b.owner === 'player') {
        for (const e of h.enemies) {
          if (!e.alive) continue;
          if (b.pos.distanceToSquared(e.pos) > (e.radius + _c.length() + 5) ** 2) continue;
          const r = segDist2(b.pos, _c, e.pos);
          if (r.d2 < e.radius * e.radius) { h.onEnemyHit(e, b.dmg, r.point.clone(), false); fx.hitSpark(r.point); this.shotsHit++; hit = true; break; }
        }
      } else if (h.player.alive) {
        const r = segDist2(b.pos, _c, h.player.pos);
        if (r.d2 < h.player.radius * h.player.radius) { h.onPlayerHit(b.dmg, r.point.clone()); fx.hitSpark(r.point); hit = true; }
      }
      b.pos.add(_c);
      if (hit || b.life <= 0 || b.pos.y < 0) { this.bullets.splice(i, 1); continue; }
      fx.tracerGlow(b.pos, b.owner === 'enemy');
      const im = b.owner === 'player' ? this.tracerP : this.tracerE;
      const idx = b.owner === 'player' ? np++ : ne++;
      if (idx >= MAX_BULLETS) continue;
      dummy.position.copy(b.pos);
      dummy.lookAt(_a.copy(b.pos).add(b.vel));
      dummy.updateMatrix();
      im.setMatrixAt(idx, dummy.matrix);
    }
    this.tracerP.count = Math.min(np, MAX_BULLETS); this.tracerE.count = Math.min(ne, MAX_BULLETS);
    this.tracerP.instanceMatrix.needsUpdate = true; this.tracerE.instanceMatrix.needsUpdate = true;
    // --- Misiles ---
    for (const m of this.missiles) {
      if (!m.active) continue;
      m.life -= dt;
      m.speed = Math.min(m.owner === 'player' ? 720 : 470, m.speed + 420 * dt);
      const tg = m.target;
      if (tg && tg.alive) {
        const dist = m.pos.distanceTo(tg.pos);
        _a.copy(tg.pos).addScaledVector(tg.vel, Math.min(1.2, dist / m.speed) * 0.8).sub(m.pos).normalize();
        const ang = m.dir.angleTo(_a);
        if (ang > 1.5) m.target = null; // ha pasado de largo: pierde el blanco
        else if (ang > 1e-4) {
          const k = Math.min(1, (m.turn * dt) / ang);
          m.dir.lerp(_a, k).normalize();
        }
      }
      _c.copy(m.dir).multiplyScalar(m.speed * dt);
      let boom = m.life <= 0;
      const victims: Target[] = m.owner === 'player' ? h.enemies : [h.player];
      for (const e of victims) {
        if (!e.alive) continue;
        const r = segDist2(m.pos, _c, e.pos);
        if (r.d2 < (e.radius + 9) ** 2) {
          boom = true;
          if (m.owner === 'player') h.onEnemyHit(e, 85, e.pos.clone(), true); else h.onPlayerHit(26, e.pos.clone());
          break;
        }
      }
      m.pos.add(_c);
      const ground = h.heightAt(m.pos.x, m.pos.z);
      if (m.pos.y < ground + 1) { boom = true; if (ground <= 0) fx.splash(m.pos); }
      fx.smokeStreak(_a.copy(m.pos).sub(_c).addScaledVector(m.dir, -3), _b.copy(m.pos).addScaledVector(m.dir, -3), 7, q => fx.missileSmoke(q));
      m.mesh.position.copy(m.pos);
      m.mesh.lookAt(_a.copy(m.pos).sub(m.dir));
      if (boom) { m.active = false; m.mesh.visible = false; fx.explosion(m.pos, 0.6); }
    }
    // --- Power-ups ---
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const p = this.pickups[i];
      p.life -= dt;
      p.mesh.children[0].rotation.y += dt * 2;
      p.mesh.children[1].rotation.set(Math.sin(t * 1.3) * 0.6, t * 1.7, 0);
      p.mesh.position.y += Math.sin(t * 2 + i) * dt * 6;
      if (h.player.alive && p.pos.distanceTo(h.player.pos) < 34) { h.onPickup(p.kind); this.removePickup(i); continue; }
      if (p.life <= 0) this.removePickup(i);
    }
  }

  clear() {
    this.bullets.length = 0;
    this.tracerP.count = 0; this.tracerE.count = 0;
    for (const m of this.missiles) { m.active = false; m.mesh.visible = false; }
    while (this.pickups.length) this.removePickup(0);
    this.shotsFired = 0; this.shotsHit = 0;
  }

  dispose() {
    this.clear();
    this.scene.remove(this.tracerP, this.tracerE);
    this.missiles.forEach(m => this.scene.remove(m.mesh));
    this.disposables.forEach(d => d.dispose());
  }
}

import * as THREE from 'three';
import './three-compat';

/**
 * Sistema de partículas en un solo draw call (Points + ShaderMaterial).
 * Cada partícula: posición, velocidad, color inicial→final, tamaño inicial→final, vida.
 */
export class Particles {
  points: THREE.Points;
  private max: number;
  private pos: Float32Array; private col: Float32Array; private size: Float32Array; private alpha: Float32Array;
  private vel: Float32Array; private c0: Float32Array; private c1: Float32Array;
  private s0: Float32Array; private s1: Float32Array; private life: Float32Array; private maxLife: Float32Array;
  private drag: Float32Array; private rise: Float32Array;
  private cursor = 0;
  private geo: THREE.BufferGeometry; private mat: THREE.ShaderMaterial;

  constructor(scene: THREE.Scene, max: number, additive: boolean) {
    this.max = max;
    this.pos = new Float32Array(max * 3); this.col = new Float32Array(max * 3);
    this.size = new Float32Array(max); this.alpha = new Float32Array(max);
    this.vel = new Float32Array(max * 3); this.c0 = new Float32Array(max * 3); this.c1 = new Float32Array(max * 3);
    this.s0 = new Float32Array(max); this.s1 = new Float32Array(max);
    this.life = new Float32Array(max); this.maxLife = new Float32Array(max).fill(1);
    this.drag = new Float32Array(max); this.rise = new Float32Array(max);
    this.geo = new THREE.BufferGeometry();
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('pcolor', new THREE.BufferAttribute(this.col, 3));
    this.geo.setAttribute('psize', new THREE.BufferAttribute(this.size, 1));
    this.geo.setAttribute('palpha', new THREE.BufferAttribute(this.alpha, 1));
    this.mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      uniforms: { scale: { value: 400 } },
      vertexShader: `
        attribute vec3 pcolor; attribute float psize; attribute float palpha;
        uniform float scale; varying vec3 vC; varying float vA;
        void main(){
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          float dz = -mv.z;
          vC = pcolor; vA = palpha * smoothstep(6.0, 30.0, dz);
          gl_PointSize = vA > 0.0 ? min(psize * scale / max(dz, 1.0), 110.0) : 0.0;
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        varying vec3 vC; varying float vA;
        void main(){
          vec2 d = gl_PointCoord - 0.5; float r = length(d) * 2.0;
          if (r > 1.0) discard;
          float a = (1.0 - r * r) * vA;
          gl_FragColor = vec4(vC, a);
        }`,
    });
    this.points = new THREE.Points(this.geo, this.mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
  }

  setScale(h: number, fovDeg: number) {
    this.mat.uniforms.scale.value = h / (2 * Math.tan(THREE.MathUtils.degToRad(fovDeg) / 2));
  }

  emit(p: THREE.Vector3, v: THREE.Vector3, life: number, c0: THREE.Color, c1: THREE.Color, s0: number, s1: number, drag = 0.5, rise = 0) {
    const i = this.cursor; this.cursor = (this.cursor + 1) % this.max;
    const i3 = i * 3;
    this.pos[i3] = p.x; this.pos[i3 + 1] = p.y; this.pos[i3 + 2] = p.z;
    this.vel[i3] = v.x; this.vel[i3 + 1] = v.y; this.vel[i3 + 2] = v.z;
    this.c0[i3] = c0.r; this.c0[i3 + 1] = c0.g; this.c0[i3 + 2] = c0.b;
    this.c1[i3] = c1.r; this.c1[i3 + 1] = c1.g; this.c1[i3 + 2] = c1.b;
    this.s0[i] = s0; this.s1[i] = s1; this.life[i] = life; this.maxLife[i] = life;
    this.drag[i] = drag; this.rise[i] = rise;
  }

  update(dt: number) {
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.life[i] -= dt;
      const i3 = i * 3;
      const k = Math.max(0, 1 - this.drag[i] * dt);
      this.vel[i3] *= k; this.vel[i3 + 1] = this.vel[i3 + 1] * k + this.rise[i] * dt; this.vel[i3 + 2] *= k;
      this.pos[i3] += this.vel[i3] * dt; this.pos[i3 + 1] += this.vel[i3 + 1] * dt; this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
      const t = 1 - Math.max(0, this.life[i]) / this.maxLife[i];
      this.col[i3] = this.c0[i3] + (this.c1[i3] - this.c0[i3]) * t;
      this.col[i3 + 1] = this.c0[i3 + 1] + (this.c1[i3 + 1] - this.c0[i3 + 1]) * t;
      this.col[i3 + 2] = this.c0[i3 + 2] + (this.c1[i3 + 2] - this.c0[i3 + 2]) * t;
      this.size[i] = this.s0[i] + (this.s1[i] - this.s0[i]) * t;
      this.alpha[i] = this.life[i] > 0 ? Math.min(1, (1 - t) * 1.6) : 0;
    }
    (this.geo.attributes.position as THREE.BufferAttribute).needsUpdate = true;
    (this.geo.attributes.pcolor as THREE.BufferAttribute).needsUpdate = true;
    (this.geo.attributes.psize as THREE.BufferAttribute).needsUpdate = true;
    (this.geo.attributes.palpha as THREE.BufferAttribute).needsUpdate = true;
  }

  clear() { this.life.fill(0); this.alpha.fill(0); }
  dispose() { this.geo.dispose(); this.mat.dispose(); }
}

const _v = new THREE.Vector3(), _z = new THREE.Vector3(), _s = new THREE.Vector3();
const C = (h: string) => new THREE.Color(h);
const FIRE0 = C('#fff3b0'), FIRE1 = C('#ff4a10'), EMBER = C('#ff9a30'), DARK = C('#200a05');
const SMOKE0 = C('#4a4038'), SMOKE1 = C('#a89a90'), WHITE = C('#ffffff'), TRAIL1 = C('#ffd9c8');
const SPARK0 = C('#fff8d0'), SPARK1 = C('#ff8a20'), RED = C('#ff3020');

/** Fachada de efectos: fuego (aditivo) + humo (normal). */
export class Effects {
  fire: Particles; smoke: Particles;
  constructor(scene: THREE.Scene) {
    this.smoke = new Particles(scene, 1800, false);
    this.fire = new Particles(scene, 1600, true);
    this.smoke.points.renderOrder = 1; this.fire.points.renderOrder = 2;
  }
  rnd(s: number) { return _v.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize().multiplyScalar(s * (0.3 + Math.random() * 0.7)); }

  explosion(p: THREE.Vector3, scale = 1, vel?: THREE.Vector3) {
    const base = vel ? vel.clone().multiplyScalar(0.25) : new THREE.Vector3();
    for (let i = 0; i < 36 * scale; i++) this.fire.emit(p, this.rnd(70 * scale).add(base), 0.5 + Math.random() * 0.6, FIRE0, FIRE1, 14 * scale, 34 * scale, 2.2, 6);
    for (let i = 0; i < 26 * scale; i++) this.fire.emit(p, this.rnd(220 * scale).add(base), 0.4 + Math.random() * 0.8, SPARK0, SPARK1, 2.5, 0.8, 1.2, -30);
    for (let i = 0; i < 26 * scale; i++) this.smoke.emit(p, this.rnd(45 * scale).add(base), 1.6 + Math.random() * 1.6, SMOKE0, SMOKE1, 18 * scale, 60 * scale, 1.4, 10);
  }
  hitSpark(p: THREE.Vector3) {
    for (let i = 0; i < 6; i++) this.fire.emit(p, this.rnd(90), 0.25, SPARK0, SPARK1, 3, 1, 2);
  }
  tracerGlow(p: THREE.Vector3, enemy: boolean) { this.fire.emit(p, _z, 0.03, enemy ? RED : SPARK0, enemy ? RED : EMBER, 5, 4, 0); }
  muzzle(p: THREE.Vector3, v: THREE.Vector3) { this.fire.emit(p, v, 0.06, WHITE, EMBER, 4, 2, 0); }
  trail(p: THREE.Vector3, v: THREE.Vector3) { this.smoke.emit(p, v, 0.7, WHITE, TRAIL1, 0.9, 2.2, 0.4); }
  missileSmoke(p: THREE.Vector3) {
    this.smoke.emit(p, this.rnd(4), 2.2, C('#e8e2dc'), C('#b8aca4'), 3, 14, 0.8, 3);
    this.fire.emit(p, this.rnd(6), 0.12, FIRE0, FIRE1, 5, 2, 0);
  }
  /** Emite humo a lo largo de un segmento para que la estela sea continua aunque baje el FPS. */
  smokeStreak(a: THREE.Vector3, b: THREE.Vector3, spacing: number, fn: (p: THREE.Vector3) => void) {
    const n = Math.min(12, Math.max(1, Math.ceil(a.distanceTo(b) / spacing)));
    for (let i = 0; i < n; i++) fn(_s.copy(a).lerp(b, (i + Math.random()) / n));
  }
  damageSmoke(p: THREE.Vector3, heavy: boolean) {
    this.smoke.emit(p, this.rnd(5), 1.3, DARK, SMOKE0, 4, heavy ? 16 : 9, 0.6, 4);
    if (heavy) this.fire.emit(p, this.rnd(5), 0.25, FIRE0, FIRE1, 5, 3, 0);
  }
  splash(p: THREE.Vector3) {
    for (let i = 0; i < 40; i++) this.smoke.emit(p, _v.set((Math.random() - 0.5) * 60, 40 + Math.random() * 90, (Math.random() - 0.5) * 60), 1.6, WHITE, C('#cfe6ee'), 8, 22, 0.6, -60);
  }
  update(dt: number) { this.fire.update(dt); this.smoke.update(dt); }
  setScale(h: number, fov: number) { this.fire.setScale(h, fov); this.smoke.setScale(h, fov); }
  clear() { this.fire.clear(); this.smoke.clear(); }
  dispose() { this.fire.dispose(); this.smoke.dispose(); }
}

import * as THREE from 'three';
import { buildPlane } from './models';
import type { PlaneKind, PlaneModel } from './models';
import type { Combat, Target } from './combat';
import type { Effects } from './effects';
import { ARENA_RADIUS } from './world';

export type EnemyKind = Exclude<PlaneKind, 'player'>;
interface Spec { hp: number; speed: number; turn: number; radius: number; score: number; fireRate: number; missiles: boolean; name: string }
export const ENEMY_SPECS: Record<EnemyKind, Spec> = {
  fighter: { hp: 40, speed: 205, turn: 0.85, radius: 11, score: 100, fireRate: 7, missiles: false, name: 'Caza' },
  interceptor: { hp: 28, speed: 285, turn: 0.95, radius: 10, score: 150, fireRate: 9, missiles: true, name: 'Interceptor' },
  bomber: { hp: 260, speed: 135, turn: 0.32, radius: 26, score: 400, fireRate: 5, missiles: false, name: 'Bombardero' },
  ace: { hp: 120, speed: 255, turn: 1.25, radius: 11, score: 600, fireRate: 11, missiles: true, name: 'As enemigo' },
};

export interface Difficulty { dmg: number; hp: number; aim: number; aggro: number }

export class Enemy implements Target {
  pos = new THREE.Vector3(); vel = new THREE.Vector3();
  yaw = 0; pitch = 0; roll = 0; speed: number;
  hp: number; maxHp: number; radius: number; alive = true; wreck = 0;
  fireCd = 1 + Math.random() * 2; missileCd = 6 + Math.random() * 6; burst = 0;
  state: 'attack' | 'break' = 'attack'; stateT = 0; breakYaw = 0; breakPitch = 0;
  model: PlaneModel; smokeT = 0; spin = 0;
  kind: EnemyKind;
  constructor(kind: EnemyKind, hpMul: number) {
    this.kind = kind;
    const s = ENEMY_SPECS[kind];
    this.hp = this.maxHp = s.hp * hpMul; this.speed = s.speed; this.radius = s.radius;
    this.model = buildPlane(kind);
  }
}

const _d = new THREE.Vector3(), _f = new THREE.Vector3(), _p = new THREE.Vector3(), _q = new THREE.Vector3();
const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

export function forwardOf(yaw: number, pitch: number, out: THREE.Vector3) {
  return out.set(-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch));
}

/** Composición de cada oleada. */
export function waveRoster(n: number): EnemyKind[] {
  const list: EnemyKind[] = [];
  const fighters = 2 + Math.min(6, Math.floor(n * 1.2));
  for (let i = 0; i < fighters; i++) list.push('fighter');
  if (n >= 2) for (let i = 0; i < Math.min(4, n - 1); i++) list.push('interceptor');
  if (n >= 3) for (let i = 0; i < Math.min(3, Math.floor((n - 1) / 2)); i++) list.push('bomber');
  if (n >= 4) for (let i = 0; i < Math.min(3, Math.floor((n - 2) / 2)); i++) list.push('ace');
  return list;
}

export interface EnemyCtx {
  player: Target; playerFwd: THREE.Vector3; combat: Combat; fx: Effects; diff: Difficulty;
  heightAt: (x: number, z: number) => number; onFire: (dist: number) => void; onMissile: () => void; onWreckDown: (e: Enemy) => void;
}

export class EnemyManager {
  list: Enemy[] = [];
  private scene: THREE.Scene;
  constructor(scene: THREE.Scene) { this.scene = scene; }

  get alive() { return this.list.filter(e => e.alive); }

  spawnWave(n: number, playerPos: THREE.Vector3, playerYaw: number, diff: Difficulty) {
    const roster = waveRoster(n);
    roster.forEach((k, i) => {
      const e = new Enemy(k, diff.hp * (1 + (n - 1) * 0.08));
      if (n === 1) {
        // Primera oleada: una patrulla delante que huye en formación (persecución)
        const side = (i - (roster.length - 1) / 2) * 110, d = 420 + Math.random() * 160;
        const fx = -Math.sin(playerYaw), fz = -Math.cos(playerYaw);
        e.pos.set(playerPos.x + fx * d + fz * -side, playerPos.y + 20 + (Math.random() - 0.5) * 60, playerPos.z + fz * d - fx * -side);
        e.yaw = playerYaw + (Math.random() - 0.5) * 0.25;
        e.state = 'break'; e.stateT = 4 + i * 0.8; e.breakYaw = e.yaw; e.breakPitch = 0.05;
      } else {
        // Aparecen por delante del jugador, repartidos en abanico, volando hacia él
        const a = playerYaw + (i / Math.max(1, roster.length - 1) - 0.5) * 1.6 + (Math.random() - 0.5) * 0.2;
        const d = 1300 + Math.random() * 600 + (k === 'bomber' ? 400 : 0);
        e.pos.set(playerPos.x - Math.sin(a) * d, Math.max(180, playerPos.y + (Math.random() - 0.4) * 160), playerPos.z - Math.cos(a) * d);
        e.yaw = Math.atan2(-(playerPos.x - e.pos.x), -(playerPos.z - e.pos.z)) + (Math.random() - 0.5) * 0.4;
      }
      forwardOf(e.yaw, 0, e.vel).multiplyScalar(e.speed);
      this.scene.add(e.model.root);
      this.list.push(e);
    });
  }

  private steer(e: Enemy, target: THREE.Vector3, dt: number, ctx: EnemyCtx) {
    const s = ENEMY_SPECS[e.kind];
    _d.subVectors(target, e.pos);
    // Evitar el suelo / techo / salir de la zona
    const ground = ctx.heightAt(e.pos.x, e.pos.z);
    let wantPitch = Math.asin(THREE.MathUtils.clamp(_d.y / (_d.length() || 1), -1, 1));
    let wantYaw = Math.atan2(-_d.x, -_d.z);
    if (e.pos.y < ground + 110) wantPitch = 0.5;
    else if (e.pos.y > 950) wantPitch = -0.35;
    if (Math.hypot(e.pos.x, e.pos.z) > ARENA_RADIUS) wantYaw = Math.atan2(e.pos.x, e.pos.z);
    wantPitch = THREE.MathUtils.clamp(wantPitch, -0.7, 0.75);
    const yerr = wrap(wantYaw - e.yaw);
    const yawRate = THREE.MathUtils.clamp(yerr * 2.2, -s.turn, s.turn);
    e.yaw += yawRate * dt;
    e.pitch += THREE.MathUtils.clamp(wantPitch - e.pitch, -s.turn * dt, s.turn * dt);
    const wantRoll = THREE.MathUtils.clamp(yawRate * 1.2, -1.25, 1.25);
    e.roll += (wantRoll - e.roll) * Math.min(1, dt * 3);
    return yerr;
  }

  update(dt: number, ctx: EnemyCtx) {
    const P = ctx.player;
    for (let i = this.list.length - 1; i >= 0; i--) {
      const e = this.list[i];
      const s = ENEMY_SPECS[e.kind];
      if (!e.alive) {
        // Derribado: cae en barrena echando fuego hasta tocar el agua
        e.wreck += dt; e.spin += dt * (e.kind === 'bomber' ? 1.2 : 5);
        e.pitch = Math.max(-1.2, e.pitch - dt * 0.6); e.roll = e.spin;
        forwardOf(e.yaw, e.pitch, e.vel).multiplyScalar(e.speed * 0.9);
        e.vel.y -= 40 * e.wreck;
        _q.copy(e.pos);
        e.pos.addScaledVector(e.vel, dt);
        ctx.fx.smokeStreak(_q, e.pos, 6, q => ctx.fx.damageSmoke(q, true));
        if (e.pos.y <= ctx.heightAt(e.pos.x, e.pos.z) + 2 || e.wreck > 6) {
          ctx.fx.explosion(e.pos, e.kind === 'bomber' ? 1.6 : 1); if (e.pos.y < 6) ctx.fx.splash(e.pos);
          ctx.onWreckDown(e);
          this.remove(i);
          continue;
        }
        this.syncModel(e);
        continue;
      }
      const dist = e.pos.distanceTo(P.pos);
      e.stateT -= dt;
      let yerr = 0;
      if (e.state === 'attack') {
        // Punto de tiro anticipado
        const lead = Math.min(1.6, dist / 950) * ctx.diff.aim;
        _p.copy(P.pos).addScaledVector(P.vel, lead);
        if (e.kind === 'bomber') { _p.set(-e.pos.x * 0.2, 260, -e.pos.z * 0.2); if (dist < 1400) _p.copy(P.pos).addScaledVector(P.vel, 3); }
        yerr = this.steer(e, _p, dt, ctx);
        // Si pasa muy cerca o tiene al jugador encima, rompe el combate un momento
        if (dist < 110 && e.kind !== 'bomber') { e.state = 'break'; e.stateT = 1.8 + Math.random() * 1.5; e.breakYaw = e.yaw + (Math.random() < 0.5 ? 1 : -1) * 1.6; e.breakPitch = (Math.random() - 0.3) * 0.6; }
      } else {
        _p.copy(e.pos).addScaledVector(forwardOf(e.breakYaw, e.breakPitch, _q), 500);
        yerr = this.steer(e, _p, dt, ctx);
        if (e.stateT <= 0) e.state = 'attack';
      }
      // Movimiento
      const spd = e.speed * (e.state === 'break' ? 1.15 : 1) * (dist > 1800 ? 1.25 : 1);
      forwardOf(e.yaw, e.pitch, e.vel).multiplyScalar(spd);
      e.pos.addScaledVector(e.vel, dt);
      // Disparo
      forwardOf(e.yaw, e.pitch, _f);
      _d.subVectors(P.pos, e.pos).normalize();
      const facing = _f.dot(_d);
      e.fireCd -= dt; e.missileCd -= dt;
      if (P.alive) {
        if (e.kind === 'bomber') {
          if (dist < 700 && e.fireCd <= 0) {
            e.fireCd = 1 / s.fireRate * (2 - ctx.diff.aggro);
            this.shoot(e, _q.copy(e.pos).addScaledVector(_d, 22).setY(e.pos.y + 4), _d, ctx, 0.05);
          }
        } else if (e.state === 'attack' && dist < 750 && facing > 0.985 && Math.abs(yerr) < 0.2 && e.fireCd <= 0) {
          if (e.burst <= 0) e.burst = 6 + Math.floor(Math.random() * 6);
          e.burst--; e.fireCd = e.burst <= 0 ? 1.2 / ctx.diff.aggro : 1 / s.fireRate;
          _p.copy(P.pos).addScaledVector(P.vel, dist / 950);
          _d.subVectors(_p, e.pos).normalize();
          this.shoot(e, _q.copy(e.pos).addScaledVector(_f, 10), _d, ctx, 0.03 / ctx.diff.aim);
        }
        if (s.missiles && e.missileCd <= 0 && dist > 450 && dist < 1500 && facing > 0.9) {
          e.missileCd = (e.kind === 'ace' ? 9 : 14) / ctx.diff.aggro;
          ctx.combat.fireMissile(_q.copy(e.pos).addScaledVector(_f, 8).setY(e.pos.y - 2), _f, e.speed + 60, 'enemy', P);
          ctx.onMissile();
        }
      }
      // Humo si está dañado
      if (e.hp < e.maxHp * 0.5) {
        e.smokeT -= dt;
        if (e.smokeT <= 0) { e.smokeT = 0.05; ctx.fx.damageSmoke(_q.copy(e.pos).addScaledVector(_f, -6), e.hp < e.maxHp * 0.25); }
      }
      this.syncModel(e);
    }
  }

  private shoot(e: Enemy, from: THREE.Vector3, dir: THREE.Vector3, ctx: EnemyCtx, spread: number) {
    _p.copy(dir).add(_d.set((Math.random() - 0.5) * spread, (Math.random() - 0.5) * spread, (Math.random() - 0.5) * spread)).normalize();
    ctx.combat.fireBullet(from, _p.multiplyScalar(950), 'enemy', 4 * ctx.diff.dmg);
    ctx.onFire(e.pos.distanceTo(ctx.player.pos));
  }

  private syncModel(e: Enemy) {
    const r = e.model.root;
    r.position.copy(e.pos);
    r.rotation.set(e.pitch, e.yaw, e.roll, 'YXZ');
    if (e.model.prop) e.model.prop.children.forEach(c => { c.rotation.z += 0.9; });
    e.model.glow.visible = e.alive;
  }

  /** Aplica daño; devuelve true si lo derriba. */
  damage(e: Enemy, dmg: number) {
    if (!e.alive) return false;
    e.hp -= dmg;
    if (e.state === 'attack' && e.kind !== 'bomber' && Math.random() < 0.08) {
      e.state = 'break'; e.stateT = 1.2 + Math.random(); e.breakYaw = e.yaw + (Math.random() < 0.5 ? 1.3 : -1.3); e.breakPitch = (Math.random() - 0.5) * 0.8;
    }
    if (e.hp <= 0) { e.alive = false; e.wreck = 0; return true; }
    return false;
  }

  private remove(i: number) {
    const e = this.list[i];
    this.scene.remove(e.model.root);
    (e.model.glow.material as THREE.Material).dispose();
    this.list.splice(i, 1);
  }

  clear() { while (this.list.length) this.remove(0); }
}

import * as THREE from 'three';
import { setupRenderer } from './three-compat';
import { World } from './world';
import { Effects } from './effects';
import { Combat, PICKUP_INFO } from './combat';
import type { PickupKind, Target } from './combat';
import { EnemyManager, ENEMY_SPECS } from './enemies';
import type { Difficulty, Enemy } from './enemies';
import { Player, MAX_MISSILES } from './player';
import { Input } from './input';
import { Sfx } from './audio';
import { disposeModels } from './models';
import { drawHud } from './hudcanvas';

export type Mode = 'menu' | 'play' | 'paused' | 'over';
export type DiffId = 'facil' | 'normal' | 'dificil';
export const DIFFS: Record<DiffId, Difficulty & { label: string; sub: string }> = {
  facil: { label: 'Recluta', sub: 'Enemigos lentos de gatillo', dmg: 0.55, hp: 0.8, aim: 0.7, aggro: 0.75 },
  normal: { label: 'Piloto', sub: 'El reto equilibrado', dmg: 1, hp: 1, aim: 1, aggro: 1 },
  dificil: { label: 'As', sub: 'Sin piedad en el cielo', dmg: 1.5, hp: 1.3, aim: 1.25, aggro: 1.3 },
};

export interface HudData {
  score: number; hp: number; missiles: number; maxMissiles: number; boost: number; wave: number; enemies: number;
  speed: number; alt: number; combo: number; rapidT: number; shieldT: number; locked: boolean; lockName: string;
  missileWarn: boolean; outOfBounds: boolean; lowAlt: boolean;
}
export interface Summary { score: number; wave: number; kills: number; accuracy: number; bestCombo: number; time: number; record: number; newRecord: boolean; diff: DiffId }
export type MsgKind = 'big' | 'kill' | 'warn' | 'good';
export interface GameCallbacks {
  onHud: (d: HudData) => void;
  onMessage: (text: string, kind: MsgKind) => void;
  onGameOver: (s: Summary) => void;
}

const RECORD_KEY = 'sky-ace-records';
export function loadRecords(): Record<DiffId, number> {
  try { const r = JSON.parse(localStorage.getItem(RECORD_KEY) || '{}'); return { facil: r.facil || 0, normal: r.normal || 0, dificil: r.dificil || 0 }; }
  catch { return { facil: 0, normal: 0, dificil: 0 }; }
}

const _v = new THREE.Vector3(), _w = new THREE.Vector3(), _look = new THREE.Vector3();

export class Game {
  mode: Mode = 'menu';
  input = new Input();
  sfx = new Sfx();
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera: THREE.PerspectiveCamera;
  private world: World; private fx: Effects; private combat: Combat; private enemies: EnemyManager; private player: Player;
  private overlay: HTMLCanvasElement; private octx: CanvasRenderingContext2D;
  private container: HTMLElement; private ro: ResizeObserver; private raf = 0;
  private clock = new THREE.Clock(); private t = 0;
  private cb: GameCallbacks;
  private diffId: DiffId = 'normal'; private diff: Difficulty = DIFFS.normal;
  private score = 0; private wave = 0; private kills = 0; private combo = 1; private comboT = 0; private bestCombo = 1;
  private playTime = 0; private waveClearT = -1; private deathT = -1; private shake = 0; private hurtT = 0;
  private hudT = 0; private lastHud: HudData | null = null; private camInit = false;

  constructor(container: HTMLElement, overlay: HTMLCanvasElement, cb: GameCallbacks) {
    this.container = container; this.overlay = overlay; this.cb = cb;
    this.octx = overlay.getContext('2d')!;
    this.renderer = new THREE.WebGLRenderer({ antialias: false, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(this.renderer.domElement);
    this.renderer.domElement.style.display = 'block';
    this.camera = new THREE.PerspectiveCamera(68, 1, 1, 26000);
    this.world = new World(this.scene);
    this.fx = new Effects(this.scene);
    this.combat = new Combat(this.scene);
    this.enemies = new EnemyManager(this.scene);
    this.player = new Player(this.scene);
    this.player.pos.set(-400, 240, 900);
    this.input.attach();
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(container);
    this.resize();
    this.loop();
  }

  private resize() {
    const w = Math.max(1, this.container.clientWidth), h = Math.max(1, this.container.clientHeight);
    this.renderer.setSize(w, h);
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
    const dpr = Math.min(window.devicePixelRatio, 2);
    this.overlay.width = Math.floor(w * dpr); this.overlay.height = Math.floor(h * dpr);
    this.overlay.style.width = w + 'px'; this.overlay.style.height = h + 'px';
    this.octx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.fx.setScale(h * this.renderer.getPixelRatio(), this.camera.fov);
  }

  start(diff: DiffId) {
    this.sfx.unlock();
    this.diffId = diff; this.diff = DIFFS[diff];
    this.enemies.clear(); this.combat.clear(); this.fx.clear();
    this.player.reset(); this.input.reset();
    this.score = 0; this.wave = 0; this.kills = 0; this.combo = 1; this.comboT = 0; this.bestCombo = 1;
    this.playTime = 0; this.waveClearT = -1; this.deathT = -1; this.shake = 0; this.hurtT = 0; this.camInit = false;
    this.mode = 'play';
    this.sfx.startEngine();
    this.nextWave();
  }

  pause() { if (this.mode === 'play' && this.deathT < 0) { this.mode = 'paused'; this.sfx.stopEngine(); } }
  resume() { if (this.mode === 'paused') { this.mode = 'play'; this.sfx.startEngine(); this.input.reset(); } }
  toMenu() {
    this.mode = 'menu'; this.sfx.stopEngine();
    this.enemies.clear(); this.combat.clear(); this.player.reset(); this.player.pos.set(-400, 240, 900);
  }
  setMuted(m: boolean) { this.sfx.setMuted(m); }

  private nextWave() {
    this.wave++;
    this.enemies.spawnWave(this.wave, this.player.pos, this.player.yaw, this.diff);
    this.cb.onMessage(`OLEADA ${this.wave}`, 'big');
    if (this.wave === 3) this.cb.onMessage('¡Bombarderos a la vista!', 'warn');
    if (this.wave === 4) this.cb.onMessage('¡Ases enemigos con misiles!', 'warn');
  }

  private loop = () => {
    this.raf = requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, this.clock.getDelta());
    if (this.mode !== 'paused') this.t += dt;
    this.input.update();
    if (this.mode === 'play') this.updatePlay(dt);
    else if (this.mode === 'menu' || this.mode === 'over') {
      if (this.mode === 'menu') this.player.autopilot(dt, this.t);
      this.enemies.update(dt, this.enemyCtx());
      this.fx.update(dt);
    }
    this.updateCamera(dt);
    this.world.update(this.t, this.camera);
    this.renderer.render(this.scene, this.camera);
    this.drawOverlay();
  };

  private enemyCtx() {
    return {
      player: this.player as Target, playerFwd: this.player.fwd, combat: this.combat, fx: this.fx, diff: this.diff,
      heightAt: (x: number, z: number) => this.world.heightAt(x, z),
      onFire: (d: number) => this.sfx.enemyGun(1 - Math.min(1, d / 900)),
      onMissile: () => this.cb.onMessage('¡MISIL ENEMIGO!', 'warn'),
      onWreckDown: (e: Enemy) => {
        const d = e.pos.distanceTo(this.player.pos);
        this.sfx.explosion(Math.max(0.15, 1 - d / 1500) * 0.7);
        if (d < 300) this.shake = Math.max(this.shake, 0.6);
      },
    };
  }

  private updatePlay(dt: number) {
    const P = this.player, inp = this.input.state;
    this.playTime += dt;
    if (P.alive) {
      const ground = P.fly(dt, inp, this.fx, (x, z) => this.world.heightAt(x, z));
      if (P.pos.y < ground + 4) this.crash(ground);
      if (inp.fire && P.alive) { if (P.shoot(dt, this.combat, this.fx)) this.sfx.gun(); }
      else P.gunCd = Math.max(0, P.gunCd - dt);
      P.missileCd -= dt;
      if (inp.missile) { inp.missile = false; if (P.fireMissile(this.combat)) this.sfx.missile(); else if (P.missiles <= 0) this.cb.onMessage('Sin misiles', 'warn'); }
      const lk = P.updateLock(dt, this.enemies.list);
      if (lk === 'tick') this.sfx.lockTick(); else if (lk === 'locked') this.sfx.locked();
      this.sfx.setEngine((P.speed - 200) / 200, P.boosting);
    } else {
      this.deathT -= dt;
      if (this.deathT <= 0) { this.gameOver(); return; }
    }
    this.enemies.update(dt, this.enemyCtx());
    this.combat.update(dt, this.t, {
      player: P, enemies: this.enemies.list, heightAt: (x, z) => this.world.heightAt(x, z),
      onEnemyHit: (t, dmg, _p, byMissile) => this.hitEnemy(t as Enemy, dmg, byMissile),
      onPlayerHit: (dmg) => this.hurt(dmg),
      onPickup: (k) => this.pickup(k),
    }, this.fx);
    this.fx.update(dt);
    // Combo
    if (this.comboT > 0) { this.comboT -= dt; if (this.comboT <= 0) this.combo = 1; }
    this.hurtT = Math.max(0, this.hurtT - dt);
    // Aviso de misil entrante
    let warn = false;
    for (const m of this.combat.missiles) if (m.active && m.owner === 'enemy' && m.target === P && m.pos.distanceTo(P.pos) < 1600) warn = true;
    if (warn) this.sfx.warning(this.t);
    // Fin de oleada
    if (P.alive && this.enemies.alive.length === 0) {
      if (this.waveClearT < 0) {
        this.waveClearT = 3.5;
        const bonus = 250 * this.wave;
        this.score += bonus;
        P.hp = Math.min(100, P.hp + 20); P.missiles = Math.min(MAX_MISSILES, P.missiles + 3);
        this.cb.onMessage(`OLEADA SUPERADA  +${bonus}`, 'good');
        this.sfx.fanfare();
      } else {
        this.waveClearT -= dt;
        if (this.waveClearT <= 0) { this.waveClearT = -1; this.nextWave(); }
      }
    }
    this.hudT -= dt;
    if (this.hudT <= 0) { this.hudT = 0.1; this.emitHud(warn); }
  }

  private emitHud(warn: boolean) {
    const P = this.player;
    const d: HudData = {
      score: this.score, hp: Math.max(0, P.hp), missiles: P.missiles, maxMissiles: MAX_MISSILES, boost: P.boost,
      wave: this.wave, enemies: this.enemies.alive.length, speed: Math.round(P.speed * 3.2), alt: Math.round(P.pos.y),
      combo: this.combo, rapidT: P.rapidT, shieldT: P.shieldT, locked: P.locked,
      lockName: P.lockTarget ? ENEMY_SPECS[P.lockTarget.kind].name : '', missileWarn: warn, outOfBounds: P.outOfBounds, lowAlt: P.lowAlt,
    };
    this.lastHud = d;
    this.cb.onHud(d);
  }

  private hitEnemy(e: Enemy, dmg: number, byMissile: boolean) {
    const P = this.player;
    if (!byMissile) this.sfx.hit();
    if (this.enemies.damage(e, dmg)) {
      const spec = ENEMY_SPECS[e.kind];
      const pts = spec.score * this.combo;
      this.score += pts; this.kills++;
      this.cb.onMessage(`${spec.name} derribado  +${pts}${this.combo > 1 ? `  x${this.combo}` : ''}`, 'kill');
      this.combo = Math.min(6, this.combo + (this.comboT > 0 ? 1 : 0)); this.comboT = 5;
      this.bestCombo = Math.max(this.bestCombo, this.combo);
      this.fx.explosion(e.pos, e.kind === 'bomber' ? 1.4 : 0.9, e.vel);
      const d = e.pos.distanceTo(P.pos);
      this.sfx.explosion(Math.max(0.25, 1 - d / 1400));
      this.shake = Math.max(this.shake, d < 250 ? 0.9 : 0.35);
      if (e.kind === 'bomber' || Math.random() < 0.3) this.combat.spawnPickup(e.pos.clone());
    }
  }

  private hurt(dmg: number) {
    const P = this.player;
    if (!P.alive) return;
    if (P.shieldT > 0) { this.shake = Math.max(this.shake, 0.15); return; }
    P.hp -= dmg; this.hurtT = 0.35; this.shake = Math.max(this.shake, Math.min(1, dmg / 20));
    this.sfx.hurt();
    if (P.hp <= 0) this.die();
  }

  private crash(ground: number) {
    const P = this.player;
    if (ground <= 0) this.fx.splash(P.pos); else this.fx.explosion(P.pos, 0.5);
    P.pos.y = ground + 8; P.pitch = 0.5;
    if (P.shieldT > 0) { P.shieldT = 0; this.cb.onMessage('¡Escudo perdido!', 'warn'); }
    else this.hurt(40);
    this.shake = 1;
  }

  private die() {
    const P = this.player;
    P.alive = false; P.hp = 0; P.model.root.visible = false; P.shield.visible = false;
    this.fx.explosion(P.pos, 2, P.vel);
    this.sfx.explosion(1.2); this.sfx.stopEngine();
    this.shake = 1.2; this.deathT = 2.6;
    this.cb.onMessage('¡DERRIBADO!', 'warn');
    this.emitHud(false);
  }

  private gameOver() {
    this.mode = 'over';
    const rec = loadRecords();
    const prev = rec[this.diffId];
    const newRecord = this.score > prev && this.score > 0;
    if (newRecord) { rec[this.diffId] = this.score; try { localStorage.setItem(RECORD_KEY, JSON.stringify(rec)); } catch { /* sin almacenamiento */ } }
    this.cb.onGameOver({
      score: this.score, wave: this.wave, kills: this.kills,
      accuracy: this.combat.shotsFired ? Math.round((this.combat.shotsHit / this.combat.shotsFired) * 100) : 0,
      bestCombo: this.bestCombo, time: Math.round(this.playTime), record: Math.max(prev, this.score), newRecord, diff: this.diffId,
    });
  }

  private pickup(k: PickupKind) {
    const P = this.player;
    if (k === 'repair') P.hp = Math.min(100, P.hp + 35);
    if (k === 'missiles') P.missiles = Math.min(MAX_MISSILES, P.missiles + 4);
    if (k === 'rapid') P.rapidT = 10;
    if (k === 'shield') P.shieldT = 9;
    this.sfx.pickup();
    this.cb.onMessage(PICKUP_INFO[k].label, 'good');
  }

  private updateCamera(dt: number) {
    const P = this.player, cam = this.camera;
    if (this.mode === 'menu') {
      const a = this.t * 0.12;
      _v.set(Math.sin(a) * 46, 9 + Math.sin(this.t * 0.3) * 4, Math.cos(a) * 46).add(P.pos);
      cam.position.copy(_v); cam.up.set(0, 1, 0); cam.lookAt(_look.copy(P.pos).addScaledVector(P.fwd, 10));
      this.camInit = false;
      return;
    }
    if (!P.alive || this.mode === 'over') {
      const a = this.t * 0.25;
      cam.position.lerp(_v.set(P.pos.x + Math.sin(a) * 140, P.pos.y + 50, P.pos.z + Math.cos(a) * 140), Math.min(1, dt * 2));
      cam.lookAt(P.pos);
    } else {
      // Cámara de persecución con inercia
      _v.copy(P.pos).addScaledVector(P.fwd, -32 - (P.boosting ? 8 : 0)).add(_w.set(0, 9, 0));
      if (!this.camInit) { cam.position.copy(_v); this.camInit = true; }
      cam.position.lerp(_v, 1 - Math.exp(-dt * 7));
      cam.up.set(0, 1, 0);
      cam.lookAt(_look.copy(P.pos).addScaledVector(P.fwd, 45));
      cam.rotateZ(P.roll * 0.35);
      const fov = P.boosting ? 80 : 68;
      if (Math.abs(cam.fov - fov) > 0.1) { cam.fov += (fov - cam.fov) * Math.min(1, dt * 3); cam.updateProjectionMatrix(); this.fx.setScale(this.container.clientHeight * this.renderer.getPixelRatio(), cam.fov); }
    }
    if (this.shake > 0) {
      const s = this.shake * 2.2;
      cam.position.add(_w.set((Math.random() - 0.5) * s, (Math.random() - 0.5) * s, (Math.random() - 0.5) * s));
      this.shake = Math.max(0, this.shake - dt * 1.8);
    }
  }

  private drawOverlay() {
    const w = this.container.clientWidth, h = this.container.clientHeight;
    this.octx.clearRect(0, 0, w, h);
    if (this.mode !== 'play' && this.mode !== 'paused') return;
    drawHud(this.octx, w, h, {
      camera: this.camera, player: this.player, enemies: this.enemies.list, combat: this.combat,
      islands: this.world.islands, t: this.t, hurt: this.hurtT, warn: !!this.lastHud?.missileWarn,
    });
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.input.detach();
    this.sfx.dispose();
    this.enemies.clear();
    this.combat.dispose(); this.fx.dispose(); this.world.dispose(); this.player.dispose();
    disposeModels();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import type { Combat } from './combat';
import { PICKUP_INFO } from './combat';
import type { Enemy } from './enemies';
import type { Player } from './player';
import type { Island } from './world';

export interface HudDrawData {
  camera: THREE.Camera; player: Player; enemies: Enemy[]; combat: Combat; islands: Island[];
  t: number; hurt: number; warn: boolean;
}

const _p = new THREE.Vector3();
const FONT = '600 11px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';

function project(cam: THREE.Camera, v: THREE.Vector3, w: number, h: number) {
  _p.copy(v).project(cam);
  const behind = _p.z > 1;
  return { x: (_p.x * 0.5 + 0.5) * w, y: (-_p.y * 0.5 + 0.5) * h, behind, nx: _p.x, ny: _p.y };
}

function brackets(g: CanvasRenderingContext2D, x: number, y: number, s: number) {
  const k = s * 0.4;
  g.beginPath();
  g.moveTo(x - s, y - s + k); g.lineTo(x - s, y - s); g.lineTo(x - s + k, y - s);
  g.moveTo(x + s - k, y - s); g.lineTo(x + s, y - s); g.lineTo(x + s, y - s + k);
  g.moveTo(x + s, y + s - k); g.lineTo(x + s, y + s); g.lineTo(x + s - k, y + s);
  g.moveTo(x - s + k, y + s); g.lineTo(x - s, y + s); g.lineTo(x - s, y + s - k);
  g.stroke();
}

/** Dibuja la capa de HUD 2D: retícula, marcadores de blancos, fijación, flechas y radar. */
export function drawHud(g: CanvasRenderingContext2D, w: number, h: number, d: HudDrawData) {
  const P = d.player, cam = d.camera;
  g.save();
  g.font = FONT; g.textAlign = 'center'; g.lineWidth = 1.6;

  // Viñeta de daño / aviso de misil
  if (d.hurt > 0 || d.warn) {
    const a = d.hurt > 0 ? d.hurt * 1.4 : (Math.sin(d.t * 18) * 0.5 + 0.5) * 0.35;
    const grd = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.35, w / 2, h / 2, Math.max(w, h) * 0.75);
    grd.addColorStop(0, 'rgba(255,30,20,0)'); grd.addColorStop(1, `rgba(255,30,20,${Math.min(0.6, a)})`);
    g.fillStyle = grd; g.fillRect(0, 0, w, h);
  }
  if (!P.alive) { g.restore(); return; }

  // Retícula de tiro (donde llegan las balas)
  const aim = project(cam, _p.copy(P.pos).addScaledVector(P.fwd, 520), w, h);
  if (!aim.behind) {
    g.strokeStyle = 'rgba(190,255,225,0.9)';
    g.beginPath(); g.arc(aim.x, aim.y, 14, 0, Math.PI * 2); g.stroke();
    g.beginPath();
    g.moveTo(aim.x - 24, aim.y); g.lineTo(aim.x - 8, aim.y); g.moveTo(aim.x + 8, aim.y); g.lineTo(aim.x + 24, aim.y);
    g.moveTo(aim.x, aim.y + 8); g.lineTo(aim.x, aim.y + 18);
    g.stroke();
    g.fillStyle = 'rgba(190,255,225,0.9)'; g.fillRect(aim.x - 1.5, aim.y - 1.5, 3, 3);
  }

  // Blancos
  const offscreen: Array<{ e: Enemy; dist: number; nx: number; ny: number }> = [];
  for (const e of d.enemies) {
    if (!e.alive) continue;
    const dist = e.pos.distanceTo(P.pos);
    const s = project(cam, e.pos, w, h);
    const isLock = P.lockTarget === e;
    if (!s.behind && s.x > 0 && s.x < w && s.y > 0 && s.y < h) {
      const size = Math.max(10, Math.min(34, 5200 / dist)) * (e.kind === 'bomber' ? 1.5 : 1);
      g.strokeStyle = e.kind === 'ace' ? 'rgba(216,120,255,0.95)' : 'rgba(255,90,70,0.95)';
      brackets(g, s.x, s.y, size);
      g.fillStyle = g.strokeStyle;
      g.fillText(`${Math.round(dist)}m`, s.x, s.y + size + 13);
      // barra de vida
      const bw = size * 1.6;
      g.fillStyle = 'rgba(0,0,0,0.45)'; g.fillRect(s.x - bw / 2, s.y - size - 9, bw, 3);
      g.fillStyle = e.hp / e.maxHp > 0.5 ? '#ffd166' : '#ff5a46'; g.fillRect(s.x - bw / 2, s.y - size - 9, bw * Math.max(0, e.hp / e.maxHp), 3);
      if (isLock) {
        const r = P.locked ? size + 8 : size + 8 + (1 - P.lockProgress) * 40;
        g.save(); g.translate(s.x, s.y); g.rotate(P.locked ? 0 : P.lockProgress * Math.PI);
        g.strokeStyle = P.locked ? '#5dff9a' : 'rgba(255,230,120,0.95)'; g.lineWidth = P.locked ? 2.5 : 1.6;
        g.beginPath(); g.moveTo(0, -r); g.lineTo(r, 0); g.lineTo(0, r); g.lineTo(-r, 0); g.closePath(); g.stroke();
        g.restore();
        if (P.locked) {
          g.fillStyle = '#5dff9a'; g.font = '700 12px ui-monospace, Menlo, monospace';
          g.fillText('FIJADO', s.x, s.y - size - 16); g.font = FONT;
        }
      }
    } else offscreen.push({ e, dist, nx: s.behind ? -s.nx : s.nx, ny: s.behind ? -s.ny : s.ny });
  }
  // Flechas a enemigos fuera de pantalla (los 5 más cercanos)
  offscreen.sort((a, b) => a.dist - b.dist).slice(0, 5).forEach(o => {
    let ax = o.nx, ay = o.ny; const m = Math.max(Math.abs(ax), Math.abs(ay)) || 1;
    ax /= m; ay /= m;
    const x = w / 2 + ax * (w / 2 - 40), y = h / 2 - ay * (h / 2 - 50);
    const ang = Math.atan2(-ay, ax);
    g.save(); g.translate(x, y); g.rotate(ang);
    g.fillStyle = o.e.kind === 'ace' ? 'rgba(216,120,255,0.9)' : 'rgba(255,90,70,0.9)';
    g.beginPath(); g.moveTo(14, 0); g.lineTo(-6, -9); g.lineTo(-2, 0); g.lineTo(-6, 9); g.closePath(); g.fill();
    g.restore();
  });

  // Misiles enemigos
  for (const m of d.combat.missiles) {
    if (!m.active || m.owner !== 'enemy') continue;
    const s = project(cam, m.pos, w, h);
    if (s.behind) continue;
    g.strokeStyle = Math.sin(d.t * 20) > 0 ? '#ff3030' : '#ffffff';
    g.beginPath(); g.arc(s.x, s.y, 9, 0, Math.PI * 2); g.stroke();
  }
  // Power-ups
  for (const pk of d.combat.pickups) {
    const s = project(cam, pk.pos, w, h);
    if (s.behind) continue;
    g.strokeStyle = PICKUP_INFO[pk.kind].color; g.fillStyle = g.strokeStyle;
    g.beginPath(); g.arc(s.x, s.y, 12 + Math.sin(d.t * 5) * 2, 0, Math.PI * 2); g.stroke();
    g.fillText(PICKUP_INFO[pk.kind].label, s.x, s.y - 18);
  }

  drawRadar(g, w, d);
  g.restore();
}

function drawRadar(g: CanvasRenderingContext2D, w: number, d: HudDrawData) {
  const P = d.player;
  const R = w < 640 ? 52 : 74, cx = w - R - 16, cy = R + 64, range = 2600, k = R / range;
  const fx = -Math.sin(P.yaw), fz = -Math.cos(P.yaw), rx = Math.cos(P.yaw), rz = -Math.sin(P.yaw);
  const map = (x: number, z: number) => {
    const dx = x - P.pos.x, dz = z - P.pos.z;
    let sx = (dx * rx + dz * rz) * k, sy = -(dx * fx + dz * fz) * k;
    const l = Math.hypot(sx, sy); if (l > R - 4) { sx *= (R - 4) / l; sy *= (R - 4) / l; }
    return [cx + sx, cy + sy, l] as const;
  };
  g.save();
  g.beginPath(); g.arc(cx, cy, R, 0, Math.PI * 2);
  g.fillStyle = 'rgba(8,16,30,0.55)'; g.fill();
  g.strokeStyle = 'rgba(140,255,200,0.55)'; g.lineWidth = 1.2; g.stroke();
  g.clip();
  // islas
  for (const i of d.islands) {
    const [x, y] = map(i.x, i.z);
    const dd = Math.hypot(i.x - P.pos.x, i.z - P.pos.z);
    if (dd - i.r > range) continue;
    g.fillStyle = 'rgba(120,200,120,0.25)'; g.beginPath(); g.arc(x, y, i.r * k, 0, Math.PI * 2); g.fill();
  }
  g.strokeStyle = 'rgba(140,255,200,0.18)';
  g.beginPath(); g.arc(cx, cy, R * 0.5, 0, Math.PI * 2); g.moveTo(cx - R, cy); g.lineTo(cx + R, cy); g.moveTo(cx, cy - R); g.lineTo(cx, cy + R); g.stroke();
  // barrido
  const sw = d.t * 2.2;
  const grd = g.createLinearGradient(cx, cy, cx + Math.cos(sw) * R, cy + Math.sin(sw) * R);
  grd.addColorStop(0, 'rgba(120,255,190,0)'); grd.addColorStop(1, 'rgba(120,255,190,0.35)');
  g.strokeStyle = grd; g.lineWidth = 2; g.beginPath(); g.moveTo(cx, cy); g.lineTo(cx + Math.cos(sw) * R, cy + Math.sin(sw) * R); g.stroke();
  for (const pk of d.combat.pickups) {
    const [x, y] = map(pk.pos.x, pk.pos.z);
    g.fillStyle = PICKUP_INFO[pk.kind].color; g.fillRect(x - 2.5, y - 2.5, 5, 5);
  }
  for (const e of d.enemies) {
    if (!e.alive) continue;
    const [x, y] = map(e.pos.x, e.pos.z);
    g.fillStyle = e.kind === 'ace' ? '#d878ff' : e === P.lockTarget ? '#ffe680' : '#ff5a46';
    g.beginPath(); g.arc(x, y, e.kind === 'bomber' ? 4.5 : 3, 0, Math.PI * 2); g.fill();
  }
  for (const m of d.combat.missiles) {
    if (!m.active || m.owner !== 'enemy') continue;
    const [x, y] = map(m.pos.x, m.pos.z);
    g.fillStyle = '#ffffff'; g.fillRect(x - 1.5, y - 1.5, 3, 3);
  }
  g.restore();
  // jugador
  g.fillStyle = '#9dffd0';
  g.beginPath(); g.moveTo(cx, cy - 7); g.lineTo(cx + 5, cy + 5); g.lineTo(cx, cy + 2); g.lineTo(cx - 5, cy + 5); g.closePath(); g.fill();
  g.font = FONT; g.fillStyle = 'rgba(160,255,210,0.8)'; g.textAlign = 'center';
  g.fillText('RADAR', cx, cy + R + 14);
}

/** Estado de entrada unificado (teclado + controles táctiles). */
export interface InputState {
  pitch: number;   // -1..1 (positivo = morro arriba)
  roll: number;    // -1..1 (positivo = derecha)
  fire: boolean;
  missile: boolean; // flanco: se consume al disparar
  boost: boolean;
}

export class Input {
  state: InputState = { pitch: 0, roll: 0, fire: false, missile: false, boost: false };
  /** Valores fijados por el joystick táctil. */
  touch = { pitch: 0, roll: 0, fire: false, boost: false, active: false };
  invert = false;
  onPause: (() => void) | null = null;
  onAnyKey: (() => void) | null = null;
  private keys = new Set<string>();

  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    if (this.onAnyKey) this.onAnyKey();
    if ((k === 'Escape' || k === 'KeyP') && !e.repeat) { this.onPause?.(); return; }
    if ((k === 'KeyX' || k === 'KeyM' || k === 'KeyE') && !e.repeat) this.state.missile = true;
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private blur = () => { this.keys.clear(); };

  attach() {
    window.addEventListener('keydown', this.down);
    window.addEventListener('keyup', this.up);
    window.addEventListener('blur', this.blur);
  }
  detach() {
    window.removeEventListener('keydown', this.down);
    window.removeEventListener('keyup', this.up);
    window.removeEventListener('blur', this.blur);
  }

  /** Recalcula los ejes; llamar una vez por fotograma. */
  update() {
    const k = this.keys; const s = this.state;
    let p = 0, r = 0;
    if (k.has('ArrowUp') || k.has('KeyW')) p += 1;
    if (k.has('ArrowDown') || k.has('KeyS')) p -= 1;
    if (k.has('ArrowLeft') || k.has('KeyA')) r -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) r += 1;
    if (this.invert) p = -p;
    if (this.touch.active) { p += this.touch.pitch * (this.invert ? -1 : 1); r += this.touch.roll; }
    s.pitch = Math.max(-1, Math.min(1, p));
    s.roll = Math.max(-1, Math.min(1, r));
    s.fire = k.has('Space') || k.has('KeyJ') || this.touch.fire;
    s.boost = k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.boost;
  }

  reset() {
    this.keys.clear();
    this.state = { pitch: 0, roll: 0, fire: false, missile: false, boost: false };
    this.touch.pitch = 0; this.touch.roll = 0; this.touch.fire = false; this.touch.boost = false;
  }
}

import * as THREE from 'three';
import { srgbTexture } from './three-compat';

export type PlaneKind = 'player' | 'fighter' | 'interceptor' | 'bomber' | 'ace';

interface Livery { body: string; wing: string; stripe: string; glow: string; scale: number; bomber?: boolean; delta?: boolean }
const LIVERIES: Record<PlaneKind, Livery> = {
  player: { body: '#e9eef5', wing: '#c9d3e0', stripe: '#ff7a1a', glow: '#7fd4ff', scale: 1 },
  fighter: { body: '#3b3f48', wing: '#2c3038', stripe: '#d8262a', glow: '#ff6a3a', scale: 1.4 },
  interceptor: { body: '#c9a227', wing: '#3a3324', stripe: '#1c1c1c', glow: '#ffd04a', scale: 1.25, delta: true },
  bomber: { body: '#5d6a4e', wing: '#4a553e', stripe: '#d8262a', glow: '#ff8040', scale: 3, bomber: true },
  ace: { body: '#2a1d3d', wing: '#1a1226', stripe: '#c43dff', glow: '#d07bff', scale: 1.45, delta: true },
};

let glowTex: THREE.Texture | null = null;
/** Textura de degradado radial compartida (brillos, motores, power-ups). */
export function getGlowTexture() {
  if (glowTex) return glowTex;
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d')!;
  const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.25, 'rgba(255,255,255,0.7)');
  grd.addColorStop(0.6, 'rgba(255,255,255,0.15)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  glowTex = srgbTexture(new THREE.CanvasTexture(c));
  return glowTex;
}

const cache = new Map<string, THREE.BufferGeometry>();
function geo(key: string, make: () => THREE.BufferGeometry) {
  let g = cache.get(key); if (!g) { g = make(); cache.set(key, g); } return g;
}
const matCache = new Map<string, THREE.Material>();
function mat(color: string, opts: Partial<THREE.MeshStandardMaterialParameters> = {}) {
  const key = color + JSON.stringify(opts);
  let m = matCache.get(key);
  if (!m) { m = new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.35, flatShading: true, ...opts }); matCache.set(key, m); }
  return m;
}

export interface PlaneModel { root: THREE.Group; glow: THREE.Sprite; prop?: THREE.Object3D }

/** Construye un avión de baja poligonización orientado hacia -Z. */
export function buildPlane(kind: PlaneKind): PlaneModel {
  const L = LIVERIES[kind];
  const root = new THREE.Group();
  const body = mat(L.body), wing = mat(L.wing), stripe = mat(L.stripe, { emissive: L.stripe, emissiveIntensity: 0.25 });
  const glass = mat('#1a2a3a', { metalness: 0.9, roughness: 0.1, emissive: '#3a6a9a', emissiveIntensity: 0.3 });

  const fus = new THREE.Mesh(geo('fus', () => new THREE.CylinderGeometry(0.9, 0.6, 11, 8).rotateX(Math.PI / 2)), body);
  const nose = new THREE.Mesh(geo('nose', () => new THREE.ConeGeometry(0.9, 3.4, 8).rotateX(-Math.PI / 2).translate(0, 0, -7.2)), body);
  const canopy = new THREE.Mesh(geo('canopy', () => new THREE.SphereGeometry(0.75, 10, 6).scale(1, 0.8, 2.2).translate(0, 0.8, -2.6)), glass);
  const band = new THREE.Mesh(geo('band', () => new THREE.CylinderGeometry(0.95, 0.95, 1.2, 8).rotateX(Math.PI / 2).translate(0, 0, -4.4)), stripe);
  root.add(fus, nose, canopy, band);

  if (L.delta) {
    const sh = new THREE.Shape();
    sh.moveTo(0, -3.5); sh.lineTo(6.5, 3.6); sh.lineTo(-6.5, 3.6); sh.lineTo(0, -3.5);
    const w = new THREE.Mesh(geo('delta', () => new THREE.ExtrudeGeometry(sh, { depth: 0.25, bevelEnabled: false }).rotateX(Math.PI / 2).translate(0, 0, 1.2)), wing);
    root.add(w);
    const tip = new THREE.Mesh(geo('dtip', () => new THREE.BoxGeometry(0.3, 0.3, 2.2)), stripe);
    const t2 = tip.clone(); tip.position.set(6.2, 0, 3.6); t2.position.set(-6.2, 0, 3.6); root.add(tip, t2);
  } else {
    const span = L.bomber ? 17 : 14;
    const w = new THREE.Mesh(geo('wing' + span, () => new THREE.BoxGeometry(span, 0.28, 2.6)), wing);
    w.position.set(0, -0.2, 0.2); root.add(w);
    const tip = new THREE.Mesh(geo('tip', () => new THREE.BoxGeometry(1.4, 0.3, 2.62)), stripe);
    const t2 = tip.clone(); tip.position.set(span / 2 - 0.7, -0.2, 0.2); t2.position.set(-span / 2 + 0.7, -0.2, 0.2);
    root.add(tip, t2);
  }
  const hstab = new THREE.Mesh(geo('hstab', () => new THREE.BoxGeometry(5.4, 0.2, 1.6)), wing);
  hstab.position.set(0, 0, 5.2);
  const fin = new THREE.Mesh(geo('fin', () => new THREE.BoxGeometry(0.22, 2.8, 2).translate(0, 1.4, 0)), body);
  fin.position.set(0, 0.4, 5); fin.rotation.x = -0.35;
  const finTop = new THREE.Mesh(geo('fintop', () => new THREE.BoxGeometry(0.26, 0.7, 1.2)), stripe);
  finTop.position.set(0, 2.9, 5.8);
  root.add(hstab, fin, finTop);

  let prop: THREE.Object3D | undefined;
  if (L.bomber) {
    // Motores en las alas con hélices
    const eg = geo('eng', () => new THREE.CylinderGeometry(0.6, 0.5, 3, 8).rotateX(Math.PI / 2));
    const pg = geo('prop', () => new THREE.BoxGeometry(3.2, 0.25, 0.1));
    const props = new THREE.Group();
    for (const x of [-4.5, 4.5]) {
      const e = new THREE.Mesh(eg, body); e.position.set(x, -0.3, -0.8); root.add(e);
      const p = new THREE.Mesh(pg, mat('#222222')); p.position.set(x, -0.3, -2.4); props.add(p);
    }
    root.add(props); prop = props;
    const turret = new THREE.Mesh(geo('tur', () => new THREE.SphereGeometry(0.7, 8, 6)), glass);
    turret.position.set(0, 1, 2); root.add(turret);
  }

  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: getGlowTexture(), color: L.glow, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, fog: false,
  }));
  glow.position.set(0, 0, 6.2); glow.scale.set(3.4, 3.4, 1);
  root.add(glow);
  root.scale.setScalar(L.scale);
  return { root, glow, prop };
}

/** Libera las cachés compartidas (al desmontar el juego). */
export function disposeModels() {
  cache.forEach(g => g.dispose()); cache.clear();
  matCache.forEach(m => m.dispose()); matCache.clear();
  if (glowTex) { glowTex.dispose(); glowTex = null; }
}

import * as THREE from 'three';
import { buildPlane } from './models';
import type { PlaneModel } from './models';
import type { Combat, Target } from './combat';
import type { Effects } from './effects';
import type { InputState } from './input';
import type { Enemy } from './enemies';
import { forwardOf } from './enemies';
import { getGlowTexture } from './models';
import { ARENA_RADIUS } from './world';

const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _r = new THREE.Vector3(), _u = new THREE.Vector3();
const _s = new THREE.Vector3(), _e = new THREE.Euler();

export const MAX_MISSILES = 8;

/** Avión del jugador: modelo de vuelo arcade, armas y fijación de blancos. */
export class Player implements Target {
  pos = new THREE.Vector3(0, 330, 1500); vel = new THREE.Vector3();
  fwd = new THREE.Vector3(0, 0, -1);
  yaw = 0; pitch = 0; roll = 0; speed = 240;
  hp = 100; alive = true; radius = 7;
  missiles = 6; boost = 1; boosting = false;
  rapidT = 0; shieldT = 0;
  gunCd = 0; missileCd = 0; gunSide = 1; missileSide = 1;
  lockTarget: Enemy | null = null; lockProgress = 0; locked = false;
  outOfBounds = false; lowAlt = false;
  model: PlaneModel;
  shield: THREE.Mesh;
  private trailT = 0;

  constructor(scene: THREE.Scene) {
    this.model = buildPlane('player');
    scene.add(this.model.root);
    const sm = new THREE.MeshBasicMaterial({ color: '#2fb8e8', transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false });
    this.shield = new THREE.Mesh(new THREE.IcosahedronGeometry(13, 1), sm);
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: getGlowTexture(), color: '#4fe8ff', blending: THREE.AdditiveBlending, transparent: true, opacity: 0.3, depthWrite: false }));
    halo.scale.set(40, 40, 1); this.shield.add(halo);
    this.shield.visible = false;
    scene.add(this.shield);
  }

  reset() {
    this.pos.set(0, 330, 1500); this.yaw = 0; this.pitch = 0; this.roll = 0; this.speed = 240;
    this.hp = 100; this.alive = true; this.missiles = 6; this.boost = 1;
    this.rapidT = 0; this.shieldT = 0; this.gunCd = 0; this.missileCd = 0;
    this.lockTarget = null; this.lockProgress = 0; this.locked = false;
    this.model.root.visible = true;
    this.sync();
  }

  /** Vuelo automático para la pantalla de inicio. */
  autopilot(dt: number, t: number) {
    this.roll += (0.32 + Math.sin(t * 0.3) * 0.1 - this.roll) * dt;
    this.yaw += Math.sin(this.roll) * 0.5 * dt;
    this.pitch = Math.sin(t * 0.4) * 0.08;
    this.pos.y += (240 - this.pos.y) * dt * 0.5;
    forwardOf(this.yaw, this.pitch, this.fwd);
    this.vel.copy(this.fwd).multiplyScalar(this.speed);
    this.pos.addScaledVector(this.vel, dt);
    if (this.pos.length() > 3000) this.yaw += dt * 0.4;
    this.emitTrails(dt, null);
    this.sync();
  }

  fly(dt: number, inp: InputState, fx: Effects, heightAt: (x: number, z: number) => number) {
    // Alabeo y viraje coordinado
    const rollTarget = -inp.roll * 1.2;
    this.roll += (rollTarget - this.roll) * Math.min(1, dt * 3.5);
    this.yaw += Math.sin(this.roll) * 1.45 * dt;
    // Cabeceo
    if (inp.pitch !== 0) this.pitch += inp.pitch * 1.15 * dt;
    else this.pitch *= 1 - 0.35 * dt;
    this.pitch = THREE.MathUtils.clamp(this.pitch, -1.25, 1.25);
    // Zona de combate: reconduce suavemente hacia el centro
    this.outOfBounds = Math.hypot(this.pos.x, this.pos.z) > ARENA_RADIUS;
    if (this.outOfBounds) {
      const want = Math.atan2(this.pos.x, this.pos.z);
      this.yaw += Math.atan2(Math.sin(want - this.yaw), Math.cos(want - this.yaw)) * 0.6 * dt;
    }
    if (this.pos.y > 1100) this.pitch = Math.min(this.pitch, -0.05);
    // Turbo
    this.boosting = inp.boost && this.boost > 0.02;
    if (this.boosting) this.boost = Math.max(0, this.boost - dt * 0.28);
    else this.boost = Math.min(1, this.boost + dt * 0.12);
    const target = (this.boosting ? 410 : 245) - Math.sin(this.pitch) * 40;
    this.speed += (target - this.speed) * Math.min(1, dt * 1.5);
    forwardOf(this.yaw, this.pitch, this.fwd);
    this.vel.copy(this.fwd).multiplyScalar(this.speed);
    this.pos.addScaledVector(this.vel, dt);
    const ground = heightAt(this.pos.x, this.pos.z);
    this.lowAlt = this.pos.y - ground < 70 && this.pitch < 0.05;
    this.rapidT = Math.max(0, this.rapidT - dt);
    this.shieldT = Math.max(0, this.shieldT - dt);
    this.emitTrails(dt, fx);
    this.sync();
    return ground;
  }

  /** Busca el blanco más centrado en el cono frontal y avanza la fijación. */
  updateLock(dt: number, enemies: Enemy[]): 'none' | 'tick' | 'locked' {
    let best: Enemy | null = null, bestA = 0.42;
    for (const e of enemies) {
      if (!e.alive) continue;
      const d = _a.subVectors(e.pos, this.pos); const dist = d.length();
      if (dist > 1800 || dist < 60) continue;
      const ang = this.fwd.angleTo(d);
      if (ang < bestA) { bestA = ang; best = e; }
    }
    if (best !== this.lockTarget) { this.lockTarget = best; this.lockProgress = 0; this.locked = false; return 'none'; }
    if (!best) return 'none';
    const was = this.locked; const before = this.lockProgress;
    this.lockProgress = Math.min(1, this.lockProgress + dt / 0.75);
    this.locked = this.lockProgress >= 1;
    if (this.locked && !was) return 'locked';
    if (Math.floor(before * 5) !== Math.floor(this.lockProgress * 5) && !this.locked) return 'tick';
    return 'none';
  }

  /** Dispara la ametralladora; devuelve nº de balas lanzadas. */
  shoot(dt: number, combat: Combat, fx: Effects) {
    this.gunCd -= dt;
    if (this.gunCd > 0) return 0;
    this.gunCd = this.rapidT > 0 ? 1 / 26 : 1 / 13;
    _r.set(1, 0, 0).applyEuler(_e.set(this.pitch, this.yaw, this.roll, 'YXZ'));
    // Asistencia de puntería: corrige ligeramente hacia el blanco anticipado más centrado
    let dir = _b.copy(this.fwd);
    const t = this.lockTarget;
    if (t && t.alive) {
      const dist = t.pos.distanceTo(this.pos);
      _u.copy(t.pos).addScaledVector(t.vel, dist / (this.speed + 1150)).sub(this.pos).normalize();
      if (dist < 1000 && this.fwd.angleTo(_u) < 0.09) dir = _u;
    }
    const n = this.rapidT > 0 ? 2 : 1;
    for (let i = 0; i < n; i++) {
      this.gunSide = -this.gunSide;
      _a.copy(this.pos).addScaledVector(_r, this.gunSide * 2.4).addScaledVector(this.fwd, 6);
      const s = 0.012;
      _u.copy(dir).add(_s.set((Math.random() - 0.5) * s, (Math.random() - 0.5) * s, (Math.random() - 0.5) * s)).normalize();
      combat.fireBullet(_a, _u.multiplyScalar(this.speed + 1150), 'player', 9);
      fx.muzzle(_a, this.vel);
    }
    return n;
  }

  fireMissile(combat: Combat) {
    if (this.missileCd > 0 || this.missiles <= 0) return false;
    this.missileCd = 0.45; this.missiles--;
    _r.set(1, 0, 0).applyEuler(_e.set(this.pitch, this.yaw, this.roll, 'YXZ'));
    this.missileSide = -this.missileSide;
    _a.copy(this.pos).addScaledVector(_r, this.missileSide * 4).add(_b.set(0, -2, 0));
    combat.fireMissile(_a, this.fwd, this.speed + 40, 'player', this.locked ? this.lockTarget : null);
    return true;
  }

  private emitTrails(dt: number, fx: Effects | null) {
    this.trailT -= dt;
    if (!fx || this.trailT > 0) return;
    this.trailT = 0.02;
    _r.set(1, 0, 0).applyEuler(_e.set(this.pitch, this.yaw, this.roll, 'YXZ'));
    for (const s of [-1, 1]) {
      _a.copy(this.pos).addScaledVector(_r, s * 6.6).addScaledVector(this.fwd, -1);
      fx.trail(_a, _b.copy(this.vel).multiplyScalar(0.05));
    }
  }

  sync() {
    const r = this.model.root;
    r.position.copy(this.pos);
    r.rotation.set(this.pitch, this.yaw, this.roll, 'YXZ');
    this.model.glow.scale.setScalar(this.boosting ? 6 + Math.random() * 1.5 : 3.4);
    this.shield.visible = this.shieldT > 0 && this.alive;
    this.shield.position.copy(this.pos);
    this.shield.rotation.y += 0.02;
    if (this.shieldT > 0 && this.shieldT < 2) this.shield.visible = Math.floor(this.shieldT * 8) % 2 === 0;
  }

  dispose() {
    this.shield.geometry.dispose();
    (this.shield.material as THREE.Material).dispose();
    this.shield.children.forEach(c => ((c as THREE.Sprite).material as THREE.Material).dispose());
    (this.model.glow.material as THREE.Material).dispose();
  }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

// r170 activa la gestión de color por defecto; r128 no la tiene. La desactivamos para que
// THREE.Color('#hex') y la iluminación se comporten igual en ambas versiones.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

/** GLSL compartido: conversión sRGB <-> lineal para los ShaderMaterial propios. */
export const GLSL_COLOR = `
vec3 toLin(vec3 c){ return pow(c, vec3(2.2)); }
vec3 toSRGB(vec3 c){ return pow(max(c, 0.0), vec3(1.0/2.2)); }
`;

import * as THREE from 'three';
import { GLSL_COLOR, LIGHT_K, srgbTexture } from './three-compat';

/* ---------------- Ruido de valor (procedural, sin dependencias) ---------------- */
function hash(x: number, y: number, s: number) {
  const h = Math.sin(x * 127.1 + y * 311.7 + s * 74.7) * 43758.5453;
  return h - Math.floor(h);
}
function vnoise(x: number, y: number, s: number) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi, s), b = hash(xi + 1, yi, s), c = hash(xi, yi + 1, s), d = hash(xi + 1, yi + 1, s);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
export function fbm(x: number, y: number, s: number) {
  let t = 0, amp = 0.5, f = 1;
  for (let i = 0; i < 4; i++) { t += vnoise(x * f, y * f, s + i * 13) * amp; f *= 2.03; amp *= 0.5; }
  return t;
}

/* ---------------- Paleta "hora dorada" ---------------- */
export const SUN_DIR = new THREE.Vector3(-0.35, 0.16, -0.92).normalize();
/** Color de niebla/horizonte en espacio lineal (los materiales lo codifican a sRGB al pintar). */
export const FOG_COLOR = new THREE.Color('#f2a47a').convertSRGBToLinear();
export const FOG_DENSITY = 0.00021;
export const ARENA_RADIUS = 5200;
const LAGOON_SIZE = 12000;

export interface Island { x: number; z: number; r: number; peak: number; seed: number }

export function islandHeight(i: Island, x: number, z: number) {
  const dx = x - i.x, dz = z - i.z;
  const d = Math.sqrt(dx * dx + dz * dz) / i.r;
  if (d >= 1) return -20;
  const n = fbm(x * 0.004 + i.seed, z * 0.004 - i.seed, i.seed);
  const edge = 1 - smooth(0.15, 1.0, d + (n - 0.5) * 0.35);
  const ridge = Math.pow(edge, 1.6) * (0.55 + n * 0.9);
  return ridge * i.peak - 8;
}
function smooth(a: number, b: number, x: number) {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

export class World {
  group = new THREE.Group();
  islands: Island[] = [];
  private sky: THREE.Mesh;
  private ocean: THREE.Mesh;
  private oceanMat: THREE.ShaderMaterial;
  private disposables: Array<{ dispose: () => void }> = [];
  private clouds: THREE.Sprite[] = [];
  private lagoonCanvas!: HTMLCanvasElement;
  private lagoonTex!: THREE.CanvasTexture;

  constructor(scene: THREE.Scene) {
    scene.add(this.group);
    scene.background = FOG_COLOR.clone();
    scene.fog = new THREE.FogExp2(FOG_COLOR.getHex(), FOG_DENSITY);
    // Luces
    const sun = new THREE.DirectionalLight(0xffd2a6, 2.1 * LIGHT_K);
    sun.position.copy(SUN_DIR).multiplyScalar(1000);
    const hemi = new THREE.HemisphereLight(0x8fb4ff, 0x2b4a63, 0.85 * LIGHT_K);
    const amb = new THREE.AmbientLight(0xffe0c8, 0.25 * LIGHT_K);
    this.group.add(sun, hemi, amb);
    this.sky = this.makeSky();
    this.oceanMat = this.makeOceanMaterial();
    this.ocean = new THREE.Mesh(new THREE.PlaneGeometry(40000, 40000, 1, 1), this.oceanMat);
    this.ocean.rotation.x = -Math.PI / 2;
    this.ocean.frustumCulled = false;
    this.group.add(this.sky, this.ocean);
    this.disposables.push(this.ocean.geometry, this.oceanMat);
    this.makeIslands();
    this.makeClouds();
  }

  private makeSky() {
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false, fog: false,
      uniforms: { sunDir: { value: SUN_DIR }, fogColor: { value: FOG_COLOR } },
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform vec3 sunDir; uniform vec3 fogColor; varying vec3 vDir;
        ${GLSL_COLOR}
        void main(){
          vec3 d = normalize(vDir);
          float h = clamp(d.y, -0.2, 1.0);
          vec3 zen = toLin(vec3(0.16,0.22,0.48));
          vec3 mid = toLin(vec3(0.50,0.52,0.78));
          vec3 hor = fogColor;
          vec3 col = mix(hor, mid, smoothstep(0.0, 0.22, h));
          col = mix(col, zen, smoothstep(0.2, 0.9, h));
          float s = max(dot(d, sunDir), 0.0);
          col += vec3(1.0,0.42,0.12) * pow(s, 8.0) * 0.45;
          col += vec3(1.0,0.7,0.35) * pow(s, 90.0) * 0.9;
          col += vec3(1.0,0.97,0.88) * smoothstep(0.9975, 0.9988, s);
          // bandas de nubes altas
          float band = sin(d.x*14.0 + d.z*9.0) * sin(d.z*21.0 - d.x*5.0);
          col = mix(col, vec3(1.0,0.55,0.4), smoothstep(0.55,0.95,band) * smoothstep(0.05,0.18,h) * (1.0 - smoothstep(0.25,0.5,h)) * 0.35);
          if (h < 0.0) col = fogColor;
          gl_FragColor = vec4(toSRGB(col), 1.0);
        }`,
    });
    const m = new THREE.Mesh(new THREE.SphereGeometry(12000, 32, 16), mat);
    m.frustumCulled = false; m.renderOrder = -10;
    this.disposables.push(m.geometry, mat);
    return m;
  }

  private makeOceanMaterial() {
    // Mapa de lagunas (aguas someras alrededor de las islas): textura 2D que cubre la zona de juego
    this.lagoonCanvas = document.createElement('canvas'); this.lagoonCanvas.width = this.lagoonCanvas.height = 512;
    this.lagoonTex = new THREE.CanvasTexture(this.lagoonCanvas); this.lagoonTex.flipY = false;
    this.disposables.push(this.lagoonTex);
    return new THREE.ShaderMaterial({
      fog: false,
      uniforms: {
        time: { value: 0 }, sunDir: { value: SUN_DIR }, fogColor: { value: FOG_COLOR },
        fogDensity: { value: FOG_DENSITY }, lagoon: { value: this.lagoonTex }, mapSize: { value: LAGOON_SIZE },
      },
      vertexShader: `varying vec3 vPos; void main(){ vec4 w = modelMatrix * vec4(position,1.0); vPos = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`,
      fragmentShader: `
        uniform float time; uniform vec3 sunDir; uniform vec3 fogColor; uniform float fogDensity;
        uniform sampler2D lagoon; uniform float mapSize;
        varying vec3 vPos;
        ${GLSL_COLOR}
        vec2 wave(vec2 p, vec2 dir, float f, float sp, float a){
          float ph = dot(p, dir) * f + time * sp;
          return dir * cos(ph) * a * f;
        }
        void main(){
          vec2 p = vPos.xz;
          vec2 g = wave(p, normalize(vec2(1.0,0.3)), 0.020, 1.2, 1.6)
                 + wave(p, normalize(vec2(-0.4,1.0)), 0.034, 1.7, 0.9)
                 + wave(p, normalize(vec2(0.8,-0.7)), 0.071, 2.6, 0.35)
                 + wave(p, normalize(vec2(-0.9,-0.2)), 0.13, 3.4, 0.16)
                 + wave(p, normalize(vec2(0.2,0.95)), 0.27, 4.1, 0.06);
          vec3 n = normalize(vec3(-g.x, 1.0, -g.y));
          vec3 v = normalize(cameraPosition - vPos);
          float dist = length(cameraPosition - vPos);
          float fres = 0.04 + 0.96 * pow(1.0 - max(dot(n, v), 0.0), 5.0);
          vec3 deep = toLin(vec3(0.05,0.22,0.36));
          vec3 shallow = toLin(vec3(0.12,0.62,0.66));
          float lag = texture2D(lagoon, p / mapSize + 0.5).r;
          float fl = 0.62 + 0.04 * sin(time * 1.5 + p.x * 0.05);
          float foam = smoothstep(0.16, 0.0, abs(lag - fl)) * 0.55;
          vec3 water = mix(deep, shallow, lag * 0.85);
          vec3 r = reflect(-v, n);
          vec3 skyc = mix(fogColor, toLin(vec3(0.50,0.52,0.78)), smoothstep(0.0, 0.5, r.y));
          vec3 col = mix(water, skyc, fres);
          float spec = pow(max(dot(r, sunDir), 0.0), 220.0) * 6.0 + pow(max(dot(r, sunDir), 0.0), 18.0) * 0.35;
          col += vec3(1.0,0.78,0.5) * spec;
          col = mix(col, vec3(0.95,0.95,0.9), foam * 0.6);
          float fogF = 1.0 - exp(-fogDensity * fogDensity * dist * dist);
          col = mix(col, fogColor, clamp(fogF, 0.0, 1.0));
          gl_FragColor = vec4(toSRGB(col), 1.0);
        }`,
    });
  }

  private makeIslands() {
    const defs: Array<[number, number, number, number]> = [
      [0, -600, 900, 200], [-2200, -1900, 650, 190], [2100, -2600, 750, 230], [2600, 900, 520, 150],
      [-2700, 1200, 600, 170], [-600, 2600, 480, 120], [900, -4300, 900, 300], [-3900, -3600, 560, 180],
      [4200, -1100, 420, 140], [-4400, -600, 450, 150], [3400, 3300, 600, 200], [-1500, 4300, 520, 160],
    ];
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95, metalness: 0 });
    this.disposables.push(mat);
    const lg = this.lagoonCanvas.getContext('2d')!;
    lg.fillStyle = '#000'; lg.fillRect(0, 0, 512, 512);
    lg.globalCompositeOperation = 'lighten';
    const cSand = new THREE.Color('#e8cf98'), cGrass = new THREE.Color('#4f8a3b'), cJungle = new THREE.Color('#2d5f2e');
    const cRock = new THREE.Color('#4e4136'), cTop = new THREE.Color('#5f5246'), tmp = new THREE.Color();
    defs.forEach(([x, z, r, peak], idx) => {
      const isl: Island = { x, z, r, peak, seed: idx * 7.31 + 3 };
      this.islands.push(isl);
      const k = 512 / LAGOON_SIZE, cx = (x + LAGOON_SIZE / 2) * k, cy = (z + LAGOON_SIZE / 2) * k;
      const grd = lg.createRadialGradient(cx, cy, r * k * 0.7, cx, cy, r * k * 1.3);
      grd.addColorStop(0, '#fff'); grd.addColorStop(1, '#000');
      lg.fillStyle = grd; lg.beginPath(); lg.arc(cx, cy, r * k * 1.3, 0, Math.PI * 2); lg.fill();
      const seg = 72;
      const geo = new THREE.PlaneGeometry(r * 2, r * 2, seg, seg);
      geo.rotateX(-Math.PI / 2);
      const pos = geo.attributes.position as THREE.BufferAttribute;
      const cols = new Float32Array(pos.count * 3);
      for (let i = 0; i < pos.count; i++) {
        const wx = pos.getX(i) + x, wz = pos.getZ(i) + z;
        const h = islandHeight(isl, wx, wz);
        pos.setY(i, h);
        const t = h / peak;
        if (h < 6) tmp.copy(cSand);
        else if (t < 0.45) tmp.copy(cGrass).lerp(cJungle, t / 0.45);
        else if (t < 0.8) tmp.copy(cJungle).lerp(cRock, (t - 0.45) / 0.35);
        else tmp.copy(cRock).lerp(cTop, Math.min(1, (t - 0.8) / 0.25));
        const j = (hash(i, idx, 2) - 0.5) * 0.08;
        cols[i * 3] = tmp.r + j; cols[i * 3 + 1] = tmp.g + j; cols[i * 3 + 2] = tmp.b + j;
      }
      geo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
      geo.computeVertexNormals();
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, 0, z);
      this.group.add(m);
      this.disposables.push(geo);
    });
    this.lagoonTex.needsUpdate = true;
  }

  private makeClouds() {
    const cv = document.createElement('canvas'); cv.width = 256; cv.height = 128;
    const g = cv.getContext('2d')!;
    for (let i = 0; i < 26; i++) {
      const x = 40 + Math.random() * 176, y = 50 + Math.random() * 40, rr = 18 + Math.random() * 30;
      const grd = g.createRadialGradient(x, y - rr * 0.3, rr * 0.1, x, y, rr);
      grd.addColorStop(0, 'rgba(255,248,240,0.95)');
      grd.addColorStop(0.6, 'rgba(255,214,190,0.55)');
      grd.addColorStop(1, 'rgba(240,170,150,0)');
      g.fillStyle = grd; g.beginPath(); g.arc(x, y, rr, 0, Math.PI * 2); g.fill();
    }
    const tex = srgbTexture(new THREE.CanvasTexture(cv));
    this.disposables.push(tex);
    for (let i = 0; i < 55; i++) {
      const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, fog: true, opacity: 0.9 });
      this.disposables.push(mat);
      const s = new THREE.Sprite(mat);
      const a = hash(i, 1, 9) * Math.PI * 2, d = 300 + hash(i, 2, 9) * 5600;
      s.position.set(Math.cos(a) * d, 560 + hash(i, 3, 9) * 460, Math.sin(a) * d);
      this.clouds.push(s);
      const w = 380 + hash(i, 4, 9) * 620;
      s.scale.set(w, w * 0.45, 1);
      this.group.add(s);
    }
  }

  /** Altura del terreno (o del agua, 0) en x,z. */
  heightAt(x: number, z: number) {
    let h = 0;
    for (const i of this.islands) {
      const dx = x - i.x, dz = z - i.z;
      if (dx * dx + dz * dz < i.r * i.r) h = Math.max(h, islandHeight(i, x, z));
    }
    return h;
  }

  update(t: number, cam: THREE.Camera) {
    this.oceanMat.uniforms.time.value = t;
    this.sky.position.copy(cam.position);
    this.ocean.position.x = cam.position.x;
    this.ocean.position.z = cam.position.z;
    // Las nubes se desvanecen al atravesarlas para no tapar la acción
    for (const c of this.clouds) {
      const dist = c.position.distanceTo(cam.position), d = dist / c.scale.x;
      c.visible = dist < 6500;
      (c.material as THREE.SpriteMaterial).opacity = 0.9 * Math.min(1, Math.max(0, (d - 0.35) / 0.9));
    }
  }

  dispose() { this.disposables.forEach(d => d.dispose()); }
}
